from PIL import Image

html_content = """<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>노션 기본 인터페이스와 DB 활용 실습 - 교안 프레젠테이션</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Pretendard:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #090a10;
      --card-bg: #121522;
      --card-border: rgba(255, 255, 255, 0.08);
      --text-main: #f1f5f9;
      --text-sub: #94a3b8;
      --text-muted: #64748b;
      --purple: #8b5cf6;
      --purple-light: #a78bfa;
      --cyan: #06b6d4;
      --emerald: #10b981;
      --amber: #f59e0b;
      --rose: #f43f5e;
      --gradient-purple: linear-gradient(135deg, #8b5cf6 0%, #6366f1 100%);
      --gradient-cyan: linear-gradient(135deg, #06b6d4 0%, #3b82f6 100%);
      --gradient-card: linear-gradient(180deg, rgba(255,255,255,0.03) 0%, rgba(255,255,255,0) 100%);
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background: var(--bg);
      color: var(--text-main);
      font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
      overflow: hidden;
      width: 100vw;
      height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      -webkit-font-smoothing: antialiased;
    }

    .deck-container {
      width: 1280px;
      height: 720px;
      position: relative;
      transform-origin: center center;
      flex-shrink: 0;
    }

    .slide {
      position: absolute;
      top: 0; left: 0;
      width: 1280px;
      height: 720px;
      background: var(--card-bg);
      border: 1px solid var(--card-border);
      border-radius: 20px;
      padding: 50px 70px;
      opacity: 0;
      visibility: hidden;
      transform: translateX(50px) scale(0.98);
      transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1), transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.4s;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      overflow: hidden;
      box-shadow: 0 25px 60px rgba(0,0,0,0.6);
    }

    .slide.active {
      opacity: 1;
      visibility: visible;
      transform: translateX(0) scale(1);
    }

    .slide-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      margin-bottom: 20px;
    }

    .slide-meta {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 14px;
      font-weight: 600;
      letter-spacing: 0.05em;
      color: var(--purple-light);
      text-transform: uppercase;
    }

    .slide-meta-tag {
      background: rgba(139, 92, 246, 0.15);
      border: 1px solid rgba(139, 92, 246, 0.3);
      padding: 4px 10px;
      border-radius: 6px;
    }

    .slide-number-badge {
      font-size: 28px;
      font-weight: 800;
      color: rgba(255,255,255,0.15);
    }

    .slide-title-group h2 {
      font-size: 34px;
      font-weight: 800;
      line-height: 1.25;
      color: #fff;
      margin-top: 6px;
      letter-spacing: -0.02em;
    }

    .slide-title-group p {
      font-size: 18px;
      color: var(--text-sub);
      margin-top: 8px;
      font-weight: 400;
    }

    .slide-footer {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 13px;
      color: var(--text-muted);
      border-top: 1px solid rgba(255,255,255,0.06);
      padding-top: 16px;
      margin-top: auto;
    }

    .content-body {
      flex: 1;
      display: flex;
      flex-direction: column;
      justify-content: center;
      margin: 15px 0;
      gap: 20px;
    }

    .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
    .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
    .grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
    .grid-5 { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }

    .card {
      background: var(--gradient-card);
      background-color: rgba(255,255,255,0.02);
      border: 1px solid var(--card-border);
      border-radius: 14px;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      transition: all 0.3s ease;
    }
    .card:hover {
      border-color: rgba(139, 92, 246, 0.4);
      transform: translateY(-2px);
    }
    .card-accent { border-left: 4px solid var(--purple); }
    .card-cyan { border-left: 4px solid var(--cyan); }
    .card-emerald { border-left: 4px solid var(--emerald); }
    .card-amber { border-left: 4px solid var(--amber); }

    .card-num {
      font-size: 24px;
      font-weight: 800;
      color: var(--purple-light);
    }
    .card-title {
      font-size: 20px;
      font-weight: 700;
      color: #fff;
    }
    .card-desc {
      font-size: 15px;
      color: var(--text-sub);
      line-height: 1.5;
    }

    .callout {
      background: rgba(139, 92, 246, 0.1);
      border: 1px solid rgba(139, 92, 246, 0.3);
      border-radius: 12px;
      padding: 18px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      color: var(--text-main);
      font-size: 16px;
      font-weight: 500;
    }
    .callout-icon { font-size: 24px; }

    .ai-note {
      background: rgba(245, 158, 11, 0.1);
      border: 1px solid rgba(245, 158, 11, 0.3);
      border-radius: 12px;
      padding: 16px 20px;
      color: #fef08a;
      font-size: 15px;
      display: flex;
      gap: 12px;
      align-items: center;
    }

    .summary-table {
      width: 100%;
      border-collapse: collapse;
      background: rgba(0,0,0,0.2);
      border-radius: 12px;
      overflow: hidden;
      border: 1px solid var(--card-border);
    }
    .summary-table th {
      background: rgba(255,255,255,0.06);
      color: var(--purple-light);
      padding: 14px 18px;
      text-align: left;
      font-size: 15px;
      font-weight: 700;
    }
    .summary-table td {
      padding: 14px 18px;
      border-top: 1px solid rgba(255,255,255,0.05);
      color: var(--text-main);
      font-size: 15px;
    }

    .slide-title-hero {
      height: 100%;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: flex-start;
      gap: 20px;
      padding: 0 40px;
    }
    .hero-kicker {
      background: var(--gradient-purple);
      color: white;
      padding: 6px 16px;
      border-radius: 20px;
      font-size: 14px;
      font-weight: 700;
      letter-spacing: 0.05em;
    }
    .hero-title {
      font-size: 52px;
      font-weight: 800;
      line-height: 1.15;
      background: linear-gradient(135deg, #ffffff 0%, #cbd5e1 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.03em;
    }
    .hero-sub {
      font-size: 22px;
      color: var(--text-sub);
      max-width: 800px;
      line-height: 1.5;
    }
    .hero-tags {
      display: flex;
      gap: 12px;
      margin-top: 15px;
    }
    .tag {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      padding: 8px 18px;
      border-radius: 8px;
      font-size: 15px;
      color: var(--cyan);
      font-weight: 600;
    }

    .slide-section-divider {
      height: 100%;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      text-align: center;
      gap: 16px;
    }
    .section-num {
      font-size: 64px;
      font-weight: 900;
      color: var(--purple);
      line-height: 1;
    }
    .section-title {
      font-size: 44px;
      font-weight: 800;
      color: #fff;
    }
    .section-sub {
      font-size: 20px;
      color: var(--text-sub);
      max-width: 600px;
    }

    .progress-bar {
      position: fixed;
      bottom: 0; left: 0;
      height: 4px;
      background: var(--gradient-purple);
      transition: width 0.3s ease;
      z-index: 100;
    }
    .page-indicator {
      position: fixed;
      bottom: 18px; right: 20px;
      background: rgba(18, 21, 34, 0.85);
      border: 1px solid var(--card-border);
      backdrop-filter: blur(10px);
      padding: 6px 14px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 600;
      color: var(--text-sub);
      z-index: 100;
    }
    .nav-zone {
      position: fixed; top: 0; bottom: 0; width: 12%;
      z-index: 90; cursor: pointer;
    }
    .nav-zone.left { left: 0; }
    .nav-zone.right { right: 0; }
    .help-btn {
      position: fixed; bottom: 18px; right: 90px;
      width: 32px; height: 32px; border-radius: 50%;
      background: rgba(255,255,255,0.08); border: 1px solid var(--card-border);
      color: white; font-weight: 700; cursor: pointer;
      z-index: 100; display: flex; align-items: center; justify-content: center;
      transition: all 0.2s ease;
    }
    .help-btn:hover { background: rgba(139, 92, 246, 0.4); transform: scale(1.05); }

    .help-modal {
      display: none; position: fixed; inset: 0;
      background: rgba(0,0,0,0.85); backdrop-filter: blur(8px);
      z-index: 200; justify-content: center; align-items: center;
    }
    .help-modal.active { display: flex; }
    .help-content {
      background: var(--card-bg); padding: 36px 44px; border-radius: 16px;
      max-width: 480px; width: 90%; border: 1px solid var(--card-border);
      box-shadow: 0 20px 50px rgba(0,0,0,0.8);
    }
    .help-content h3 { font-size: 22px; margin-bottom: 20px; color: #fff; border-bottom: 1px solid var(--card-border); padding-bottom: 10px; }
    .help-list { list-style: none; display: flex; flex-direction: column; gap: 12px; font-size: 15px; color: var(--text-sub); }
    .help-list b { color: var(--purple-light); display: inline-block; width: 140px; }

    @media print {
      body { overflow: visible; background: #fff !important; color: #000 !important; }
      .deck-container { transform: none !important; width: 100% !important; height: auto !important; }
      .slide {
