  <script>
    const slides = document.querySelectorAll('.slide');
    const total = slides.length;
    let current = 0;

    function scaleDeck() {
      const container = document.getElementById('deckContainer');
      const scale = Math.min(window.innerWidth / 1280, window.innerHeight / 720);
      container.style.transform = `scale(${scale})`;
    }
    window.addEventListener('resize', scaleDeck);
    scaleDeck();

    function goTo(index) {
      if (index < 0) index = 0;
      if (index >= total) index = total - 1;
      slides[current].classList.remove('active');
      current = index;
      slides[current].classList.add('active');
      document.getElementById('progressBar').style.width = `${((current + 1) / total) * 100}%`;
      document.getElementById('pageIndicator').innerText = `${current + 1} / ${total}`;
    }

    function nextSlide() { goTo(current + 1); }
    function prevSlide() { goTo(current - 1); }

    document.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') nextSlide();
      else if (e.key === 'ArrowLeft' || e.key === 'PageUp') prevSlide();
      else if (e.key === 'Home') goTo(0);
      else if (e.key === 'End') goTo(total - 1);
      else if (e.key === '?' || e.key.toLowerCase() === 'h') toggleHelp();
      else if (e.key.toLowerCase() === 'f') {
        if (!document.fullscreenElement) document.documentElement.requestFullscreen();
        else document.exitFullscreen();
      } else if (e.key.toLowerCase() === 'p') window.print();
      else if (e.key === 'Escape') document.getElementById('helpModal').classList.remove('active');
    });

    function toggleHelp() {
      document.getElementById('helpModal').classList.toggle('active');
    }

    let touchStartX = 0;
    let touchEndX = 0;
    document.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; });
    document.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      if (touchStartX - touchEndX > 50) nextSlide();
      if (touchEndX - touchStartX > 50) prevSlide();
    });
  </script>
</body>
</html>
"""

