sim_js = """
    // NOTION INTERACTIVE SIMULATION LOGIC
    function runSim11() {
      const screen = document.getElementById('simScreen11');
      screen.innerHTML = '';

      let p1 = document.createElement('div');
      screen.appendChild(p1);

      let text1 = "/# 나만의 개인 이력 DB";
      let idx1 = 0;
      let timer1 = setInterval(() => {
        if (idx1 < text1.length) {
          p1.innerHTML = text1.substring(0, idx1 + 1) + '<span class="typing-cursor"></span>';
          idx1++;
        } else {
          clearInterval(timer1);
          setTimeout(() => {
            p1.className = 'block-h1';
            p1.innerHTML = '나만의 개인 이력 DB';

            let p2 = document.createElement('div');
            screen.appendChild(p2);
            let text2 = "/## 01. 학력 및 활동 경험";
            let idx2 = 0;
            let timer2 = setInterval(() => {
              if (idx2 < text2.length) {
                p2.innerHTML = text2.substring(0, idx2 + 1) + '<span class="typing-cursor"></span>';
                idx2++;
              } else {
                clearInterval(timer2);
                setTimeout(() => {
                  p2.className = 'block-h2';
                  p2.innerHTML = '01. 학력 및 활동 경험';
                }, 300);
              }
            }, 50);
          }, 400);
        }
      }, 50);
    }

    function runSim12() {
      const screen = document.getElementById('simScreen12');
      screen.innerHTML = '';

      let item1 = document.createElement('div');
      item1.className = 'block-todo';
      item1.innerHTML = '<div class="block-todo-check" onclick="this.classList.toggle(\\'checked\\')"></div><span>[] 4주차 수요일 개인 이력 DB 생성하기</span>';
      screen.appendChild(item1);

      setTimeout(() => {
        item1.querySelector('span').innerText = '4주차 수요일 개인 이력 DB 생성하기';
      }, 800);

      setTimeout(() => {
        let item2 = document.createElement('div');
        item2.className = 'block-todo';
        item2.innerHTML = '<div class="block-todo-check checked" onclick="this.classList.toggle(\\'checked\\')"></div><span style="text-decoration: line-through; color: var(--text-sub);">나의 대표 경험 3개 속성 정리 완료</span>';
        screen.appendChild(item2);
      }, 1200);
    }
"""

