import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# Fix HTML handlers to ensure keyboard events pass correctly
content = content.replace('oninput="onLiveCalloutInput(this)"', 'oninput="onLiveCalloutInput(this)" onkeyup="onLiveCalloutInput(this)"')
content = content.replace('oninput="onLiveBookmarkInput(this)"', 'oninput="onLiveBookmarkInput(this)" onkeyup="onLiveBookmarkInput(event, this)"')

# Re-write the entire JS block for Slide 12 and 13 clean & 100% bug-free
js_marker = "// --- SLIDE 12 REAL-TIME LIVE NOTION EDITOR LOGIC ---"
idx_js = content.find(js_marker)
idx_script_end = content.find("</script>", idx_js)

if idx_js != -1 and idx_script_end != -1:
    clean_js = """// --- SLIDE 12 REAL-TIME LIVE NOTION EDITOR LOGIC ---
    let isBulletCreated = false;
    function onLiveBulletInput(input) {
      try {
        let val = input.value;
        const icon = document.getElementById('bulletDotIcon');
        const badge = document.getElementById('bulletStatusBadge');

        if (val.startsWith('- ') || val.startsWith('-')) {
          if (val.startsWith('- ')) {
            input.value = val.substring(2);
          }
          isBulletCreated = true;
          if (icon) icon.style.display = 'inline-block';
          if (badge) badge.style.display = 'flex';
          input.placeholder = "01. 카페 아르바이트 (고객 응대)";
        } else if (isBulletCreated) {
          if (icon) icon.style.display = 'inline-block';
          if (badge) badge.style.display = 'flex';
        }
      } catch (err) { console.log(err); }
    }

    let isTodoCreated = false;
    let isTodoChecked = false;

    function onLiveTodoInput(input) {
      try {
        let val = input.value;
        const btn = document.getElementById('todoCheckBtn');
        const badge = document.getElementById('todoStatusBadge');

        if (val.startsWith('[] ') || val.startsWith('[ ] ') || val.startsWith('[]')) {
          if (val.startsWith('[] ')) input.value = val.substring(3);
          else if (val.startsWith('[ ] ')) input.value = val.substring(4);

          isTodoCreated = true;
          if (btn) btn.style.display = 'flex';
          if (badge) badge.style.display = 'block';
          input.placeholder = "01. 개인 이력 메인 페이지 생성";
        } else if (isTodoCreated) {
          if (btn) btn.style.display = 'flex';
          if (badge) badge.style.display = 'block';
        }
      } catch (err) { console.log(err); }
    }

    function toggleLiveTodoCheck() {
      try {
        isTodoChecked = !isTodoChecked;
        const mark = document.getElementById('todoCheckMark');
        const btn = document.getElementById('todoCheckBtn');
        const input = document.getElementById('todoInputText');
        const badgeText = document.getElementById('todoBadgeText');

        if (isTodoChecked) {
          if (mark) mark.style.display = 'inline';
          if (btn) {
            btn.style.background = 'var(--amber)';
            btn.style.borderColor = 'var(--amber)';
          }
          if (mark) mark.style.color = '#111';
          if (input) {
            input.style.textDecoration = 'line-through';
            input.style.color = 'var(--text-sub)';
          }
          if (badgeText) {
            badgeText.innerText = '☑ 할 일 완수 완료! (취소선 적용됨)';
            badgeText.style.color = 'var(--emerald)';
          }
        } else {
          if (mark) mark.style.display = 'none';
          if (btn) {
            btn.style.background = 'rgba(245,158,11,0.15)';
            btn.style.borderColor = 'var(--amber)';
          }
          if (input) {
            input.style.textDecoration = 'none';
            input.style.color = '#fff';
          }
          if (badgeText) {
            badgeText.innerText = '☐ 미완료 상태 (네모 상자를 클릭하여 완료 표시하세요)';
            badgeText.style.color = 'var(--amber)';
          }
        }
      } catch (err) { console.log(err); }
    }

    // --- SLIDE 13 REAL-TIME CALLOUT & BOOKMARK LOGIC ---
    let isCalloutCreated = false;
    function onLiveCalloutInput(input) {
      try {
        let val = input.value;
        const box = document.getElementById('calloutContainerBox');
        const icon = document.getElementById('calloutEmojiIcon');
        const badge = document.getElementById('calloutStatusBadge');

        // '/콜아웃' 또는 '/callout' 또는 '/' 포함 시 발동
        if (val.includes('/콜아웃') || val.includes('/callout') || val.startsWith('/')) {
          let clean = val.replace(/^\\/콜아웃[\\s]*/, '').replace(/^\\/callout[\\s]*/, '').replace(/^\\/[\\s]*/, '');
          input.value = clean;
          isCalloutCreated = true;
          if (box) {
            box.style.background = 'rgba(139,92,246,0.22)';
            box.style.border = '2px solid #8b5cf6';
            box.style.boxShadow = '0 0 15px rgba(139,92,246,0.3)';
          }
          if (icon) icon.style.display = 'inline-block';
          if (badge) badge.style.display = 'flex';
          input.placeholder = "오늘의 취업 목표: 나만의 포트폴리오 노션 완성";
        } else if (isCalloutCreated) {
          if (box) box.style.background = 'rgba(139,92,246,0.22)';
          if (icon) icon.style.display = 'inline-block';
          if (badge) badge.style.display = 'flex';
        }
      } catch (err) { console.log(err); }
    }

    let isBookmarkCreated = false;
    function onLiveBookmarkInput(e, input) {
      try {
        let val = input.value;
        const card = document.getElementById('bookmarkCardPreview');
        const inputWrap = document.getElementById('bookmarkInputWrapper');

        // Space나 Enter 키를 누르거나, URL 입력을 마쳤을 때 정확하게 변환
        let isKeyTrigger = (e && (e.code === 'Space' || e.code === 'Enter' || e.key === ' ' || e.key === 'Enter'));
        let isUrlMatch = val.includes('notion.so') || val.includes('http://') || val.includes('https://') || val.endsWith('.com') || val.endsWith('.kr');

        if (isUrlMatch && (isKeyTrigger || val.endsWith(' '))) {
          isBookmarkCreated = true;
          if (card) card.style.display = 'flex';
          if (inputWrap) inputWrap.style.display = 'none'; // 주소창은 깔끔하게 숨기고 북마크 카드 표시
        }
      } catch (err) { console.log(err); }
    }
"""
    content = content[:idx_js] + clean_js + content[idx_script_end:]
    print("JS cleanly replaced without syntax errors!")

with open(html_path, 'w', encoding='utf-8') as f:
