        <div style="background: #11131f; border: 2px solid var(--purple-light); border-radius: 14px; padding: 18px; margin-top: 16px;">
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px;">
            <div style="font-size: 14px; color: var(--purple-light); font-weight: 800;">
