slide18_js = """

    // --- SLIDE 18 NOTION DB VIEW SWITCHER LOGIC ---
    function switchNotionDbView18(viewType) {
      try {
        const tableView = document.getElementById('dbViewTable18');
        const boardView = document.getElementById('dbViewBoard18');
        const galleryView = document.getElementById('dbViewGallery18');

        const btnTable = document.getElementById('viewBtn18_table');
        const btnBoard = document.getElementById('viewBtn18_board');
        const btnGallery = document.getElementById('viewBtn18_gallery');

        // Hide all views first
        if (tableView) tableView.style.display = 'none';
        if (boardView) boardView.style.display = 'none';
        if (galleryView) galleryView.style.display = 'none';

        // Reset button styles
        [btnTable, btnBoard, btnGallery].forEach(btn => {
          if (btn) {
            btn.style.background = '#252836';
            btn.style.color = '#fff';
            btn.style.border = '1px solid rgba(255,255,255,0.2)';
            btn.style.fontWeight = '700';
