        });

        // Activate selected view
        if (viewType === 'table') {
          if (tableView) tableView.style.display = 'block';
          if (btnTable) {
            btnTable.style.background = 'var(--purple-light)';
            btnTable.style.color = '#000';
            btnTable.style.fontWeight = '800';
