        if (!isInlineDbCreated20 && isTrigger && isSpacePressed) {
          isInlineDbCreated20 = true;
          if (inputWrap) inputWrap.style.display = 'none';
          if (preview) preview.style.display = 'flex';
        }
      } catch (err) { console.log(err); }
