import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Add Jump Popup UI Element to presentation.html
old_controls = '<!-- UI Controls -->'
new_controls = """<!-- UI Controls -->
  <!-- SMART NUMBER JUMP BADGE POPUP -->
  <div id="numJumpBadge" style="display: none; position: fixed; top: 30px; right: 40px; background: rgba(18, 21, 34, 0.95); border: 2px solid var(--purple-light); backdrop-filter: blur(12px); color: #fff; padding: 12px 24px; border-radius: 16px; font-size: 18px; font-weight: 800; z-index: 300; box-shadow: 0 10px 30px rgba(0,0,0,0.8); animation: popIn 0.2s ease;">
    <span>🚀 Go to Slide: </span><span id="numJumpValue" style="color: var(--purple-light); font-size: 24px; font-weight: 900; margin-left: 6px;"></span>
  </div>"""

if content.find(old_controls) != -1:
    content = content.replace(old_controls, new_controls)
    print("Added numJumpBadge UI element!")

# 2. Update goTo function to save URL hash (#25) and update keydown handler
old_goto = """    function goTo(index) {
      try {
        if (index < 0) index = 0;
        if (index >= total) index = total - 1;
        slides[current].classList.remove('active');
        current = index;
        slides[current].classList.add('active');

        const pBar = document.getElementById('progressBar');
        const pInd = document.getElementById('pageIndicator');
        if (pBar) pBar.style.width = `${((current + 1) / total) * 100}%`;
        if (pInd) pInd.innerText = `${current + 1} / ${total}`;"""

new_goto = """    function goTo(index) {
      try {
        if (index < 0) index = 0;
        if (index >= total) index = total - 1;
        slides[current].classList.remove('active');
        current = index;
        slides[current].classList.add('active');

        const pBar = document.getElementById('progressBar');
        const pInd = document.getElementById('pageIndicator');
        if (pBar) pBar.style.width = `${((current + 1) / total) * 100}%`;
        if (pInd) pInd.innerText = `${current + 1} / ${total}`;

        // Save current slide number in URL hash for F5 reload memory!
        window.location.hash = '#' + (current + 1);"""

if content.find(old_goto) != -1:
    content = content.replace(old_goto, new_goto)
    print("Updated goTo function to save URL Hash (#25)!")

# 3. Add Smart Number Buffer & Debounce Jump Logic to keydown event
old_keydown_block = """    // Safe Keyboard Event Listener (Supports Spacebar & All Navigation Keys)
    document.addEventListener('keydown', (e) => {
      try {
        if (e.target.isContentEditable || e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
          return; // Ignore navigation when typing inside input
        }
        if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ' || e.code === 'Space') nextSlide();
        else if (e.key === 'ArrowLeft' || e.key === 'PageUp') prevSlide();
        else if (e.key === 'Home') goTo(0);
        else if (e.key === 'End') goTo(total - 1);
        else if (e.key === '?' || e.key.toLowerCase() === 'h') toggleHelp();
        else if (e.key.toLowerCase() === 'f') {
          if (!document.fullscreenElement) document.documentElement.requestFullscreen();
          else document.exitFullscreen();
        } else if (e.key.toLowerCase() === 'p') window.print();
        else if (e.key === 'Escape') {
          const modal = document.getElementById('helpModal');
          if (modal) modal.classList.remove('active');
        }
      } catch (err) { console.log(err); }
    });"""

new_keydown_block = """    // SMART NUMBER JUMP BUFFER & DEBOUNCE VARIABLES
    let numBuffer = '';
    let numJumpTimer = null;

    function handleNumberJump(digit) {
      try {
        numBuffer += digit;
        const badge = document.getElementById('numJumpBadge');
        const valElem = document.getElementById('numJumpValue');

        if (valElem) valElem.innerText = numBuffer;
        if (badge) badge.style.display = 'flex';

        if (numJumpTimer) clearTimeout(numJumpTimer);

        // Wait 0.8 seconds (800ms) to distinguish '2' vs '24'
        numJumpTimer = setTimeout(() => {
          executeNumberJump();
        }, 800);
      } catch (err) { console.log(err); }
    }

    function executeNumberJump() {
      try {
        if (numJumpTimer) clearTimeout(numJumpTimer);
        if (numBuffer.length > 0) {
          let targetSlide = parseInt(numBuffer, 10);
          if (!isNaN(targetSlide) && targetSlide > 0) {
            goTo(targetSlide - 1); // 1-indexed to 0-indexed
          }
        }
        numBuffer = '';
        const badge = document.getElementById('numJumpBadge');
        if (badge) badge.style.display = 'none';
      } catch (err) { console.log(err); }
    }

    // Safe Keyboard Event Listener (Supports Spacebar, Numpad 0-9 & Direct Number Jump)
    document.addEventListener('keydown', (e) => {
      try {
        if (e.target.isContentEditable || e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
          return; // Ignore navigation when typing inside input
        }

        // Direct Number Key (Top Row 0-9 & Numpad 0-9)
        if (/^[0-9]$/.test(e.key) || /^Numpad[0-9]$/.test(e.code)) {
          let digit = e.key;
          if (!digit || isNaN(parseInt(digit, 10))) {
            digit = e.code.replace('Numpad', '');
          }
          if (digit && !isNaN(parseInt(digit, 10))) {
            handleNumberJump(digit);
            return;
          }
        }

        // Instant Jump on Enter key if typing numbers
        if (e.key === 'Enter' && numBuffer.length > 0) {
          executeNumberJump();
          return;
        }

        if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ' || e.code === 'Space') nextSlide();
        else if (e.key === 'ArrowLeft' || e.key === 'PageUp') prevSlide();
        else if (e.key === 'Home') goTo(0);
        else if (e.key === 'End') goTo(total - 1);
        else if (e.key === '?' || e.key.toLowerCase() === 'h') toggleHelp();
        else if (e.key.toLowerCase() === 'f') {
          if (!document.fullscreenElement) document.documentElement.requestFullscreen();
          else document.exitFullscreen();
        } else if (e.key.toLowerCase() === 'p') window.print();
        else if (e.key === 'Escape') {
          numBuffer = '';
          const badge = document.getElementById('numJumpBadge');
          if (badge) badge.style.display = 'none';
          const modal = document.getElementById('helpModal');
          if (modal) modal.classList.remove('active');
        }
      } catch (err) { console.log(err); }
    });"""

if content.find(old_keydown_block) != -1:
    content = content.replace(old_keydown_block, new_keydown_block)
    print("Added Smart Number Jump Listener & Enter Instant Jump!")

# 4. Update initial load memory from URL Hash (#25)
old_init_load = """    // Force initial slide active state
    setTimeout(() => {
      try {
        slides.forEach(s => s.classList.remove('active'));
        if (slides[0]) slides[0].classList.add('active');
        const pBar = document.getElementById('progressBar');
        const pInd = document.getElementById('pageIndicator');
        if (pBar) pBar.style.width = `${(1 / total) * 100}%`;
        if (pInd) pInd.innerText = `1 / ${total}`;
      } catch (err) { console.log(err); }
    }, 100);"""

new_init_load = """    // Force initial slide active state with URL Hash F5 memory support!
    setTimeout(() => {
      try {
        let initialSlideIdx = 0;
        const hash = window.location.hash.replace('#', '');
        if (hash) {
          const parsed = parseInt(hash, 10);
          if (!isNaN(parsed) && parsed > 0 && parsed <= total) {
            initialSlideIdx = parsed - 1;
          }
        }
        goTo(initialSlideIdx);
      } catch (err) { console.log(err); }
    }, 100);"""

if content.find(old_init_load) != -1:
    content = content.replace(old_init_load, new_init_load)
    print("Added F5 reload Hash Memory support (#25)!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Smart Number Jump & F5 Reload Memory feature fully implemented!")

