import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# Add Web Audio API Mouse Click Synthesizer for realistic "딸깍!" sound
sound_js = """
    // --- REALISTIC MOUSE CLICK SOUND SYNTHESIZER (WEB AUDIO API) ---
    function playMouseClickSound() {
      try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        if (ctx.state === 'suspended') {
          ctx.resume();
        }

        // 1. Transient Click Snap (High frequency burst)
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.type = 'triangle';
        osc.frequency.setValueAtTime(1200, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(120, ctx.currentTime + 0.03);

        gain.gain.setValueAtTime(0.35, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.035);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start();
        osc.stop(ctx.currentTime + 0.04);

        // 2. Mechanical Tactile Release Snap (Subtle secondary pop)
        setTimeout(() => {
          try {
            const osc2 = ctx.createOscillator();
            const gain2 = ctx.createGain();

            osc2.type = 'sine';
            osc2.frequency.setValueAtTime(800, ctx.currentTime);
            osc2.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.02);

            gain2.gain.setValueAtTime(0.2, ctx.currentTime);
            gain2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.025);

            osc2.connect(gain2);
            gain2.connect(ctx.destination);

            osc2.start();
            osc2.stop(ctx.currentTime + 0.03);
          } catch(e) {}
        }, 15);

      } catch (err) { console.log('Click sound audio error:', err); }
    }
"""

old_move_fn_start = "function moveCursorAndClick30(targetId, callback) {"
old_move_fn_end = "function renderStepDisplay30(stepIdx) {"

idx_fn_s = content.find(old_move_fn_start)
idx_fn_e = content.find(old_move_fn_end)

new_move_fn = """function moveCursorAndClick30(targetId, callback) {
      try {
        const card = document.getElementById(targetId);
        const cursor = document.getElementById('virtualCursor30');
        if (!card || !cursor) return;

        cursor.style.opacity = '1';
        cursor.style.display = 'block';

        // Calculate position EXACTLY AT THE BOTTOM BORDER OF EACH STEP CARD (MATCHING USER YELLOW TRIANGLE PHOTO 100%)
        const targetTop = card.offsetTop + card.offsetHeight - 4; // Touch bottom border of the card!
        const targetLeft = card.offsetLeft + (card.offsetWidth / 2) - 10; // Exactly centered horizontally!

        cursor.style.transform = 'scale(1)';
        cursor.style.top = targetTop + 'px';
        cursor.style.left = targetLeft + 'px';

        // Perform click press animation & PLAY REALISTIC "딸깍!" CLICK SOUND! (0.6s)
        setTimeout(() => {
          cursor.style.transform = 'scale(0.75) translateY(-6px)';
          card.style.transform = 'scale(0.98)';

          // PLAY "딸깍!" SOUND EFFECT HERE
          playMouseClickSound();

          setTimeout(() => {
            cursor.style.transform = 'scale(1)';
            card.style.transform = 'scale(1.03)';
            if (callback) callback();
          }, 150);
        }, 600);

      } catch (err) { console.log(err); }
    }

    """

if idx_fn_s != -1 and idx_fn_e != -1:
    content = content[:idx_fn_s] + sound_js + "\n\n    " + new_move_fn + content[idx_fn_e:]
    print("Slide 30 Mouse Click Sound Synthesizer Added Successfully!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Added realistic '딸깍!' click sound via Web Audio API!")

