html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# Add URL hash initialization on page load!
old_hash_init = """    // Touch Swipe Support
    let touchStartX = 0, touchEndX = 0;
    document.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; });
    document.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      if (touchStartX - touchEndX > 50) nextSlide();
      if (touchEndX - touchStartX > 50) prevSlide();
    });"""

new_hash_init = """    // Touch Swipe Support
    let touchStartX = 0, touchEndX = 0;
    document.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; });
    document.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      if (touchStartX - touchEndX > 50) nextSlide();
      if (touchEndX - touchStartX > 50) prevSlide();
    });

    // AUTO RESTORE SLIDE FROM URL HASH (#35 -> Jump to Slide 35 instantly!)
    window.addEventListener('load', () => {
      try {
        if (window.location.hash) {
          let sNum = parseInt(window.location.hash.replace('#', ''), 10);
          if (!isNaN(sNum) && sNum > 0 && sNum <= total) {
            goTo(sNum - 1);
          }
        }
      } catch (e) { console.log(e); }
    });
    window.addEventListener('hashchange', () => {
      try {
        if (window.location.hash) {
          let sNum = parseInt(window.location.hash.replace('#', ''), 10);
          if (!isNaN(sNum) && sNum > 0 && sNum <= total && (sNum - 1) !== current) {
            goTo(sNum - 1);
          }
        }
      } catch (e) { console.log(e); }
    });"""

if content.find(old_hash_init) != -1:
    content = content.replace(old_hash_init, new_hash_init)
    print("URL Hash Restoration Added Successfully!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: URL Hash Restoration Added Successfully!")

