import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Update CSS for .page-indicator and .help-btn
old_css = """    .page-indicator {
      position: fixed;
      bottom: 18px; right: 20px;
      background: rgba(18, 21, 34, 0.85);
      border: 1px solid var(--card-border);
      backdrop-filter: blur(10px);
      padding: 6px 14px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 600;
      color: var(--text-sub);
      z-index: 100;
    }
    .nav-zone {
      position: fixed; top: 0; bottom: 0; width: 12%;
      z-index: 90; cursor: pointer;
    }
    .nav-zone.left { left: 0; }
    .nav-zone.right { right: 0; }
    .help-btn {
      position: fixed; bottom: 18px; right: 90px;
      width: 32px; height: 32px; border-radius: 50%;
      background: rgba(255,255,255,0.08); border: 1px solid var(--card-border);
      color: white; font-weight: 700; cursor: pointer;
      z-index: 100; display: flex; align-items: center; justify-content: center;
      transition: all 0.2s ease;
    }"""

new_css = """    .page-indicator {
      position: absolute;
      bottom: -42px; right: 0;
      background: rgba(18, 21, 34, 0.85);
      border: 1px solid var(--card-border);
      backdrop-filter: blur(10px);
      padding: 6px 14px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 600;
      color: var(--text-sub);
      z-index: 100;
      transition: opacity 0.2s ease, visibility 0.2s ease;
    }
    .nav-zone {
      position: fixed; top: 0; bottom: 0; width: 12%;
      z-index: 90; cursor: pointer;
    }
    .nav-zone.left { left: 0; }
    .nav-zone.right { right: 0; }
    .help-btn {
      position: absolute; bottom: -42px; right: 90px;
      width: 32px; height: 32px; border-radius: 50%;
      background: rgba(255,255,255,0.08); border: 1px solid var(--card-border);
      color: white; font-weight: 700; cursor: pointer;
      z-index: 100; display: flex; align-items: center; justify-content: center;
      transition: all 0.2s ease;
    }
    :fullscreen .page-indicator, :fullscreen .help-btn,
    :-webkit-full-screen .page-indicator, :-webkit-full-screen .help-btn {
      display: none !important;
      opacity: 0 !important;
      visibility: hidden !important;
    }
    body.is-fullscreen .page-indicator, body.is-fullscreen .help-btn {
      display: none !important;
      opacity: 0 !important;
      visibility: hidden !important;
    }"""

if content.find(old_css) != -1:
    content = content.replace(old_css, new_css)
    print("CSS updated: moved controls inside deckContainer area & added fullscreen hiding rules!")
else:
    print("CSS pattern not found, checking alternative...")

# 2. Move HTML controls inside #deckContainer so they anchor to bottom right outside the slide card
old_controls_html = """  </div>

  <!-- UI Controls -->
  <!-- SMART NUMBER JUMP BADGE POPUP -->
  <div id="numJumpBadge" style="display: none; position: fixed; top: 30px; right: 40px; background: rgba(18, 21, 34, 0.95); border: 2px solid var(--purple-light); backdrop-filter: blur(12px); color: #fff; padding: 12px 24px; border-radius: 16px; font-size: 18px; font-weight: 800; z-index: 300; box-shadow: 0 10px 30px rgba(0,0,0,0.8); animation: popIn 0.2s ease;">
    <span>🚀 Go to Slide: </span><span id="numJumpValue" style="color: var(--purple-light); font-size: 24px; font-weight: 900; margin-left: 6px;"></span>
  </div>
  <div class="progress-bar" id="progressBar"></div>
  <div class="page-indicator" id="pageIndicator">1 / 45</div>
  <div class="nav-zone left" onclick="prevSlide()"></div>
  <div class="nav-zone right" onclick="nextSlide()"></div>
  <button class="help-btn" onclick="toggleHelp()">?</button>"""

new_controls_html = """    <!-- UI Controls anchored outside slide inside deckContainer -->
    <div class="page-indicator" id="pageIndicator">1 / 60</div>
    <button class="help-btn" onclick="toggleHelp()">?</button>
  </div>

  <!-- UI Controls -->
  <!-- SMART NUMBER JUMP BADGE POPUP -->
  <div id="numJumpBadge" style="display: none; position: fixed; top: 30px; right: 40px; background: rgba(18, 21, 34, 0.95); border: 2px solid var(--purple-light); backdrop-filter: blur(12px); color: #fff; padding: 12px 24px; border-radius: 16px; font-size: 18px; font-weight: 800; z-index: 300; box-shadow: 0 10px 30px rgba(0,0,0,0.8); animation: popIn 0.2s ease;">
    <span>🚀 Go to Slide: </span><span id="numJumpValue" style="color: var(--purple-light); font-size: 24px; font-weight: 900; margin-left: 6px;"></span>
  </div>
  <div class="progress-bar" id="progressBar"></div>
  <div class="nav-zone left" onclick="prevSlide()"></div>
  <div class="nav-zone right" onclick="nextSlide()"></div>"""

if content.find(old_controls_html) != -1:
    content = content.replace(old_controls_html, new_controls_html)
    print("HTML controls moved inside deckContainer!")

# 3. Add JS Fullscreen Change listener to toggle body.is-fullscreen class
old_fs_key = """        else if (key.toLowerCase() === 'f') {
          if (!document.fullscreenElement) document.documentElement.requestFullscreen();
          else document.exitFullscreen();
        }"""

new_fs_key = """        else if (key.toLowerCase() === 'f') {
          if (!document.fullscreenElement) {
            document.documentElement.requestFullscreen().catch(e=>console.log(e));
          } else {
            if (document.exitFullscreen) document.exitFullscreen();
          }
        }"""

if content.find(old_fs_key) != -1:
    content = content.replace(old_fs_key, new_fs_key)

# Add fullscreenchange event handler
fs_listener_code = """
    // Fullscreen change listener to hide indicators and toggle body class
    function updateFullscreenUI() {
      const isFS = !!(document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement);
      const pInd = document.getElementById('pageIndicator');
      const hBtn = document.querySelector('.help-btn');
      if (isFS) {
        document.body.classList.add('is-fullscreen');
        if (pInd) pInd.style.display = 'none';
        if (hBtn) hBtn.style.display = 'none';
      } else {
        document.body.classList.remove('is-fullscreen');
        if (pInd) pInd.style.display = 'block';
        if (hBtn) hBtn.style.display = 'flex';
      }
    }
    document.addEventListener('fullscreenchange', updateFullscreenUI);
    document.addEventListener('webkitfullscreenchange', updateFullscreenUI);
    document.addEventListener('mozfullscreenchange', updateFullscreenUI);
"""

if content.find("document.addEventListener('fullscreenchange'") == -1:
    idx_load = content.find("window.addEventListener('load',")
    if idx_load != -1:
        content = content[:idx_load] + fs_listener_code + content[idx_load:]
        print("Fullscreen listener JS added!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Fullscreen control UI updated!")

