import os, re

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Automatic Dynamic Re-numbering Script for presentation.html
# Count total slides dynamically
slide_blocks = re.findall(r'(<div class="slide".*?>.*?</div>\s*</div>)', content, re.DOTALL)
total_count = len(re.findall(r'<div class="slide"', content))

print(f"Total HTML slide elements found: {total_count}")

# Write python code to re-number all slide badges, footers, pageIndicator and JS dynamically!
def renumber_slides(html_text):
    # Regex to find each <div class="slide"...> ... </div>
    # We will split by `<div class="slide"` and rebuild cleanly
    parts = re.split(r'(<div class="slide")', html_text)

    header = parts[0]
    slide_parts = parts[1:]

    # slide_parts comes in pairs: [1]: '<div class="slide"', [2]: ' id="..."...> ... </div>'
    slides_rebuilt = []

    slide_idx = 1
    total_slides = len(slide_parts) // 2

    for i in range(0, len(slide_parts), 2):
        s_tag = slide_parts[i]
        s_body = slide_parts[i+1]

        # 1. Update <div class="slide-number-badge">XX</div>
        s_body = re.sub(
            r'<div class="slide-number-badge">\s*\d+\s*</div>',
            f'<div class="slide-number-badge">{slide_idx}</div>',
            s_body
        )

        # 2. Update Slide footer <span>Slide XX / YY</span>
        s_body = re.sub(
            r'<span>Slide\s+\d+\s*/\s*\d+</span>',
            f'<span>Slide {slide_idx} / {total_slides}</span>',
            s_body
        )

        slides_rebuilt.append(s_tag + s_body)
        slide_idx += 1

    rebuilt_html = header + "".join(slides_rebuilt)

    # 3. Update pageIndicator initial text e.g. <div class="page-indicator" id="pageIndicator">1 / XX</div>
    rebuilt_html = re.sub(
        r'<div class="page-indicator" id="pageIndicator">.*?</div>',
        f'<div class="page-indicator" id="pageIndicator">1 / {total_slides}</div>',
        rebuilt_html
    )

    # 4. Add JS Auto Slide Numbering Initializer so JS always updates dynamically!
    auto_renumber_js = f"""
    // AUTOMATIC DYNAMIC SLIDE NUMBERING ENGINE
    function syncDynamicSlideNumbers() {{
      try {{
        const allSlides = document.querySelectorAll('.slide');
        const realTotal = allSlides.length;
        allSlides.forEach((slide, idx) => {{
          const numBadge = slide.querySelector('.slide-number-badge');
          if (numBadge) numBadge.innerText = (idx + 1);

          const footerSpans = slide.querySelectorAll('.slide-footer span');
          if (footerSpans && footerSpans.length > 1) {{
            footerSpans[footerSpans.length - 1].innerText = `Slide ${{idx + 1}} / ${{realTotal}}`;
          }}
        }});
      }} catch (e) {{ console.log(e); }}
    }}
    window.addEventListener('load', syncDynamicSlideNumbers);
"""
    if rebuilt_html.find('function syncDynamicSlideNumbers()') == -1:
        idx_load = rebuilt_html.find("window.addEventListener('load',")
        if idx_load != -1:
            rebuilt_html = rebuilt_html[:idx_load] + auto_renumber_js + rebuilt_html[idx_load:]

    return rebuilt_html, total_slides

new_content, count = renumber_slides(content)

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(new_content)

print(f"SUCCESS: Dynamic Slide Renumbering Engine Applied! Total Slides: {count}")

