import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Slide 40 HTML redesign: Single ChatGPT Window with User prompt + Action button + AI Answer Typewriter
old_s40_start = '<!-- SLIDE 40: INTERACTIVE CHATBOT TYPEWRITER & AI RESPONSE PUSH STAGE -->'
old_s40_end = '<!-- SLIDE 41:'

idx_s40_start = content.find(old_s40_start)
idx_s40_end = content.find(old_s40_end)

new_s40_html = """<!-- SLIDE 40: AUTHENTIC SINGLE CHATGPT INTERFACE WITH TYPEWRITER PROMPT & AI ANSWER -->
    <div class="slide" id="slide40Container">
      <div class="slide-header">
        <div class="slide-title-group">
          <div class="slide-meta"><span class="slide-meta-tag">04 · DEEPENING</span></div>
          <h2>AI(ChatGPT · Gemini)로 내 경험 문장 3초 만에 다듬기</h2>
          <p>단순한 경험 메모를 범용 AI 프롬프트에 넣으면 역량과 성과가 담긴 명문으로 확장해 줍니다.</p>
        </div>
        <div class="slide-number-badge">40</div>
      </div>

      <div class="content-body">
        <!-- SINGLE REALISTIC CHATGPT WINDOW (1000px wide, centered) -->
        <div style="width: 1000px; margin: 0 auto; background: #18181c; border: 1.5px solid #333342; border-radius: 18px; padding: 20px; box-shadow: 0 15px 45px rgba(0,0,0,0.6); display: flex; flex-direction: column; height: 460px; justify-content: space-between;">

          <!-- CHATGPT HEADER TOOLBAR -->
          <div style="display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #292936; padding-bottom: 10px;">
            <div style="display: flex; align-items: center; gap: 10px;">
              <span style="background: #10a37f; color: #fff; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 900; font-size: 14px;">GPT</span>
              <span style="font-size: 15px; font-weight: 800; color: #fff;">ChatGPT 4o / Gemini Live 시뮬레이터</span>
            </div>
            <div style="font-size: 12px; color: #10b981; font-weight: 800; background: rgba(16,185,129,0.15); border: 1px solid rgba(16,185,129,0.4); padding: 3px 10px; border-radius: 12px;">
              ● AI 실무 프롬프트 확장 모드
            </div>
          </div>

          <!-- CHAT MESSAGES SCROLL AREA -->
          <div id="s40ChatScrollArea" style="flex: 1; overflow-y: auto; padding: 12px 10px; display: flex; flex-direction: column; gap: 16px; scroll-behavior: smooth;">

            <!-- USER MESSAGE (RIGHT ALIGNED CHAT BUBBLE - APPEARS FIRST VIA TYPEWRITER) -->
            <div id="s40UserBubble" style="align-self: flex-end; max-width: 82%; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 14px 18px; opacity: 0; transform: translateY(10px); transition: all 0.5s ease;">
              <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: right;">👤 나 (사용자 입력)</div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.6; font-family: monospace;">
                <span id="s40PromptText"></span><span id="s40PromptCursor" style="color: #8b5cf6; font-weight: 900; animation: pulse 0.6s infinite;">|</span>
              </div>
            </div>

            <!-- AI RESPONSE MESSAGE (LEFT ALIGNED CHAT BUBBLE - APPEARS ON CLICK VIA TYPEWRITER) -->
            <div id="s40AiBubble" style="align-self: flex-start; max-width: 88%; background: rgba(16,185,129,0.08); border: 1.5px solid #10b981; border-radius: 16px 16px 16px 2px; padding: 16px 20px; opacity: 0; transform: translateY(15px); transition: all 0.6s ease; display: none;">
              <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                <span style="font-size: 16px;">✨</span>
                <span style="font-size: 12.5px; color: #6ee7b7; font-weight: 900;">AI 취업 컨설턴트 답변 (노션 DB 이식용)</span>
              </div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.7; font-weight: 600;">
                <span id="s40AiAnswerText"></span><span id="s40AiCursor" style="color: #10b981; font-weight: 900; display: inline;">|</span>
              </div>
            </div>

          </div>

          <!-- FOOTER ACTION BAR (CLICK BUTTON TO SEND & SCROLL) -->
          <div style="border-top: 1px solid #292936; padding-top: 12px; display: flex; align-items: center; justify-content: space-between; gap: 12px;">
            <div style="font-size: 12.5px; color: var(--text-sub);">
              💡 <b>프롬프트(명령어 + 단순경험)</b> 입력 완료 ➔ 우측 버튼을 누르면 AI가 전문 문장으로 답변합니다!
