import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Update HTML Markup for Slide 40:
# Set user bubble to width: fit-content / max-width: 82% with display: inline-block inside align-self: flex-end container
# Ensure user bubble & text are 100% left-aligned (text-align: left) so text grows left-to-right from the left edge of the bubble!
# Keep blinking cursor active at the end after typing finishes!

old_bubble_html = """            <!-- USER MESSAGE (RIGHT ALIGNED CONTAINER, LEFT-TO-RIGHT TYPEWRITER DISPLAY) -->
            <div id="s40UserBubble" style="align-self: flex-end; max-width: 82%; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 14px 18px; opacity: 0; transform: translateY(10px); transition: all 0.5s ease; text-align: left;">
              <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: left;">👤 나 (사용자 입력)</div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.6; font-family: 'Pretendard', monospace; text-align: left; white-space: pre-wrap;">
                <span id="s40PromptText"></span><span id="s40PromptCursor" style="color: #8b5cf6; font-weight: 900; animation: pulse 0.6s infinite;">|</span>
              </div>
            </div>"""

new_bubble_html = """            <!-- USER MESSAGE (RIGHT ALIGNED OUTER CONTAINER, CHAT BUBBLE MAPS FIRST, TYPING LEFT-TO-RIGHT) -->
            <div id="s40UserWrapper" style="align-self: flex-end; width: 100%; display: flex; justify-content: flex-end; opacity: 0; transform: translateY(10px); transition: all 0.5s ease;">
              <div id="s40UserBubble" style="width: fit-content; max-width: 82%; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 14px 18px; text-align: left;">
                <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: left;">👤 나 (사용자 입력)</div>
                <div style="font-size: 13.5px; color: #fff; line-height: 1.65; font-family: 'Pretendard', sans-serif; text-align: left; white-space: pre-wrap;">
                  <span id="s40PromptText"></span><span id="s40PromptCursor" style="color: #a78bfa; font-weight: 900; display: inline-block; animation: pulse 0.6s infinite; margin-left: 2px;">|</span>
                </div>
              </div>
            </div>"""

if content.find(old_bubble_html) != -1:
    content = content.replace(old_bubble_html, new_bubble_html)
    print("Slide 40 User Bubble HTML markup updated!")

# 2. Update JS Logic for Slide 40:
# - User wrapper maps first (fades in)
# - Typewriter types from left to right inside the mapped chat bubble
# - Cursor keeps blinking at the end of user typing!
# - When AI answer generates, cursor blinks at the end of AI answer as well!

old_js_run = """        // Step 1: User bubble fades in (0.3s)
        setTimeout(() => {
          userBubble.style.opacity = '1';
          userBubble.style.transform = 'translateY(0)';

          // Step 2: Typewriter effect for User Prompt (Command + Simple Experience Memo)
          let charIdx = 0;
          s40UserTypeInterval = setInterval(() => {
            if (charIdx < s40UserPromptText.length) {
              promptElem.innerText += s40UserPromptText.charAt(charIdx);
              charIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40UserTypeInterval);
            }
          }, 20);
        }, 300);"""

new_js_run = """        // Step 1: User chat wrapper maps first onto canvas (0.3s)
        const userWrapper = document.getElementById('s40UserWrapper');
        setTimeout(() => {
          if (userWrapper) {
            userWrapper.style.opacity = '1';
            userWrapper.style.transform = 'translateY(0)';
          }

          // Step 2: Typewriter types left-to-right inside mapped bubble
          let charIdx = 0;
          s40UserTypeInterval = setInterval(() => {
            if (charIdx < s40UserPromptText.length) {
              promptElem.innerText += s40UserPromptText.charAt(charIdx);
              charIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40UserTypeInterval);
              // Cursor stays blinking at the end!
              if (promptCursor) promptCursor.style.display = 'inline-block';
            }
          }, 18);
        }, 300);"""

if content.find(old_js_run) != -1:
    content = content.replace(old_js_run, new_js_run)
    print("Slide 40 JS runSlide40Animation updated!")

# Ensure AI Answer cursor keeps blinking at the end of AI response as well!
old_ai_js = """            } else {
              clearInterval(s40AiTypeInterval);
              if (aiCursor) aiCursor.style.display = 'none';
            }"""

new_ai_js = """            } else {
              clearInterval(s40AiTypeInterval);
              if (aiCursor) aiCursor.style.display = 'inline-block'; // Cursor keeps blinking at end!
            }"""

if content.find(old_ai_js) != -1:
    content = content.replace(old_ai_js, new_ai_js)
    print("Slide 40 JS AI Cursor blink updated!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Slide 40 Typewriter Alignment & Blinking Cursor Logic Implemented!")

