import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Add keyframes blink for cursor blinking to CSS if not present
if content.find('@keyframes cursorBlink') == -1:
    css_cursor_blink = """
    @keyframes cursorBlink {
      0%, 100% { opacity: 1; }
      50% { opacity: 0; }
    }
    .blinking-cursor {
      display: inline-block !important;
      width: 2px;
      height: 16px;
      background-color: var(--purple-light);
      margin-left: 3px;
      vertical-align: middle;
      animation: cursorBlink 0.7s infinite !important;
    }
    .blinking-cursor-green {
      display: inline-block !important;
      width: 2px;
      height: 16px;
      background-color: #10b981;
      margin-left: 3px;
      vertical-align: middle;
      animation: cursorBlink 0.7s infinite !important;
    }
"""
    idx_style = content.find('</style>')
    if idx_style != -1:
        content = content[:idx_style] + css_cursor_blink + content[idx_style:]
        print("CSS cursorBlink keyframes added!")

# 2. Update Slide 40 HTML markup for User Bubble:
# Fix user bubble width: FIXED 82% width so the bubble maps first at full size without expanding as text types!
old_user_bubble_html = """            <!-- USER MESSAGE (RIGHT ALIGNED OUTER CONTAINER, CHAT BUBBLE MAPS FIRST, TYPING LEFT-TO-RIGHT) -->
