                <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: left;">👤 나 (사용자 입력)</div>
                <div style="font-size: 13.5px; color: #fff; line-height: 1.65; font-family: 'Pretendard', sans-serif; text-align: left; white-space: pre-wrap;">
                  <span id="s40PromptText"></span><span id="s40PromptCursor" style="color: #a78bfa; font-weight: 900; display: inline-block; animation: pulse 0.6s infinite; margin-left: 2px;">|</span>
                </div>
              </div>
            </div>"""

new_user_bubble_html = """            <!-- USER MESSAGE (FIXED FULL 82% WIDTH CHAT BUBBLE MAPS FIRST AT STABLE POSITION) -->
            <div id="s40UserWrapper" style="align-self: flex-end; width: 100%; display: flex; justify-content: flex-end; opacity: 0; transform: translateY(10px); transition: all 0.5s ease;">
