                <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: left;">👤 나 (사용자 입력)</div>
                <div style="font-size: 13.5px; color: #fff; line-height: 1.65; font-family: 'Pretendard', sans-serif; text-align: left; white-space: pre-wrap; min-height: 54px;">
                  <span id="s40PromptText"></span><span id="s40PromptCursor" class="blinking-cursor"></span>
                </div>
              </div>
            </div>"""

if content.find(old_user_bubble_html) != -1:
    content = content.replace(old_user_bubble_html, new_user_bubble_html)
    print("Slide 40 User Bubble HTML updated to fixed width!")

# 3. Update AI Response Bubble HTML:
old_ai_bubble_html = """            <!-- AI RESPONSE MESSAGE (LEFT ALIGNED CHAT BUBBLE) -->
            <div id="s40AiBubble" style="align-self: flex-start; max-width: 88%; background: rgba(16,185,129,0.08); border: 1.5px solid #10b981; border-radius: 16px 16px 16px 2px; padding: 16px 20px; opacity: 0; transform: translateY(15px); transition: all 0.6s ease; display: none;">
              <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                <span style="font-size: 16px;">✨</span>
                <span style="font-size: 12.5px; color: #6ee7b7; font-weight: 900;">AI 취업 컨설턴트 추천 문장</span>
              </div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.7; font-weight: 600; white-space: pre-wrap;">
                <span id="s40AiAnswerText"></span><span id="s40AiCursor" style="color: #10b981; font-weight: 900; display: inline;">|</span>
              </div>
            </div>"""

new_ai_bubble_html = """            <!-- AI RESPONSE MESSAGE (FIXED FULL 88% WIDTH CHAT BUBBLE MAPS FIRST AT STABLE POSITION) -->
            <div id="s40AiBubble" style="align-self: flex-start; width: 88%; background: rgba(16,185,129,0.08); border: 1.5px solid #10b981; border-radius: 16px 16px 16px 2px; padding: 16px 20px; opacity: 0; transform: translateY(15px); transition: all 0.6s ease; display: none;">
              <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                <span style="font-size: 16px;">✨</span>
                <span style="font-size: 12.5px; color: #6ee7b7; font-weight: 900;">AI 취업 컨설턴트 추천 문장</span>
              </div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.7; font-weight: 600; white-space: pre-wrap; min-height: 48px;">
                <span id="s40AiAnswerText"></span><span id="s40AiCursor" class="blinking-cursor-green"></span>
              </div>
            </div>"""

if content.find(old_ai_bubble_html) != -1:
    content = content.replace(old_ai_bubble_html, new_ai_bubble_html)
    print("Slide 40 AI Bubble HTML updated to fixed width & green blinking cursor!")

# 4. Update JS logic to ensure cursors are explicitly displayed with class blinking-cursor
old_js_run = """        // Reset
        const userWrapper = document.getElementById('s40UserWrapper');
        if (userWrapper) {
          userWrapper.style.opacity = '0';
          userWrapper.style.transform = 'translateY(10px)';
        }
        aiBubble.style.display = 'none';
        aiBubble.style.opacity = '0';
        promptElem.innerText = '';
        aiTextElem.innerText = '';
        if (promptCursor) promptCursor.style.display = 'inline';
        if (aiCursor) aiCursor.style.display = 'none';"""

new_js_run = """        // Reset
        const userWrapper = document.getElementById('s40UserWrapper');
        if (userWrapper) {
          userWrapper.style.opacity = '0';
          userWrapper.style.transform = 'translateY(10px)';
        }
        aiBubble.style.display = 'none';
        aiBubble.style.opacity = '0';
        promptElem.innerText = '';
        aiTextElem.innerText = '';
        if (promptCursor) promptCursor.style.display = 'inline-block';
        if (aiCursor) aiCursor.style.display = 'none';"""

if content.find(old_js_run) != -1:
    content = content.replace(old_js_run, new_js_run)

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Slide 40 Fixed Width Chat Bubble & Dynamic Blinking Cursor Engine Applied!")

