import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# 1. Update HTML Markup for Slide 40:
# Fix user bubble: set width: fit-content (not fixed 82%), with text-align: left so text starts cleanly from the left edge of the mapped bubble without empty right padding causing right-aligned initial text look!
# Completely remove aiCursor (|) from AI response HTML so AI answer NEVER blinks any cursor!

old_user_bubble_html = """            <!-- USER MESSAGE (FIXED FULL 82% WIDTH CHAT BUBBLE MAPS FIRST AT STABLE POSITION) -->
            <div id="s40UserWrapper" style="align-self: flex-end; width: 100%; display: flex; justify-content: flex-end; opacity: 0; transform: translateY(10px); transition: all 0.5s ease;">
              <div id="s40UserBubble" style="width: 82%; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 14px 18px; text-align: left;">
                <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: left;">👤 나 (사용자 입력)</div>
                <div style="font-size: 13.5px; color: #fff; line-height: 1.65; font-family: 'Pretendard', sans-serif; text-align: left; white-space: pre-wrap; min-height: 54px;">
                  <span id="s40PromptText"></span><span id="s40PromptCursor" class="blinking-cursor"></span>
                </div>
              </div>
            </div>"""

new_user_bubble_html = """            <!-- USER MESSAGE (RIGHT ALIGNED BUBBLE, CHAT BUBBLE MAPS FIRST, TEXT STARTS 100% LEFT-ALIGNED) -->
            <div id="s40UserWrapper" style="align-self: flex-end; max-width: 82%; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 14px 18px; text-align: left; opacity: 0; transform: translateY(10px); transition: all 0.5s ease;">
              <div style="font-size: 11.5px; color: #a78bfa; font-weight: 800; margin-bottom: 4px; text-align: left;">👤 나 (사용자 입력)</div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.65; font-family: 'Pretendard', sans-serif; text-align: left; white-space: pre-wrap;">
                <span id="s40PromptText"></span><span id="s40PromptCursor" class="blinking-cursor"></span>
              </div>
            </div>"""

if content.find(old_user_bubble_html) != -1:
    content = content.replace(old_user_bubble_html, new_user_bubble_html)
    print("Slide 40 User Bubble HTML updated to left-aligned flow!")

# Remove cursor element completely from AI Response HTML
old_ai_bubble_html = """            <!-- AI RESPONSE MESSAGE (FIXED FULL 88% WIDTH CHAT BUBBLE MAPS FIRST AT STABLE POSITION) -->
            <div id="s40AiBubble" style="align-self: flex-start; width: 88%; background: rgba(16,185,129,0.08); border: 1.5px solid #10b981; border-radius: 16px 16px 16px 2px; padding: 16px 20px; opacity: 0; transform: translateY(15px); transition: all 0.6s ease; display: none;">
              <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                <span style="font-size: 16px;">✨</span>
                <span style="font-size: 12.5px; color: #6ee7b7; font-weight: 900;">AI 취업 컨설턴트 추천 문장</span>
              </div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.7; font-weight: 600; white-space: pre-wrap; min-height: 48px;">
                <span id="s40AiAnswerText"></span><span id="s40AiCursor" class="blinking-cursor-green"></span>
              </div>
            </div>"""

new_ai_bubble_html = """            <!-- AI RESPONSE MESSAGE (LEFT ALIGNED CHAT BUBBLE - NO CURSOR) -->
            <div id="s40AiBubble" style="align-self: flex-start; max-width: 88%; background: rgba(16,185,129,0.08); border: 1.5px solid #10b981; border-radius: 16px 16px 16px 2px; padding: 16px 20px; opacity: 0; transform: translateY(15px); transition: all 0.6s ease; display: none;">
              <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                <span style="font-size: 16px;">✨</span>
                <span style="font-size: 12.5px; color: #6ee7b7; font-weight: 900;">AI 취업 컨설턴트 추천 문장</span>
              </div>
              <div style="font-size: 13.5px; color: #fff; line-height: 1.7; font-weight: 600; white-space: pre-wrap;">
                <span id="s40AiAnswerText"></span>
              </div>
            </div>"""

if content.find(old_ai_bubble_html) != -1:
    content = content.replace(old_ai_bubble_html, new_ai_bubble_html)
    print("Slide 40 AI Bubble HTML updated: cursor completely removed!")

# 2. Update JS Logic for Slide 40:
# - User cursor blinks ONLY until triggerS40SendAI() is clicked! When clicked, display = 'none' !
# - AI answer typewriter types out text smoothly without any cursor!

old_trigger_js = """    function triggerS40SendAI() {
      try {
        if (isS40Sent) return;
        isS40Sent = true;

        const aiBubble = document.getElementById('s40AiBubble');
        const aiTextElem = document.getElementById('s40AiAnswerText');
        const promptCursor = document.getElementById('s40PromptCursor');
        const aiCursor = document.getElementById('s40AiCursor');
        const scrollArea = document.getElementById('s40ChatScrollArea');

        if (!aiBubble || !aiTextElem) return;

        // Hide user prompt cursor
        if (promptCursor) promptCursor.style.display = 'none';

        // Play Click Sound
        if (typeof playMouseClickSound === 'function') playMouseClickSound();

        // Show AI bubble with fade & scroll
        aiBubble.style.display = 'block';
        setTimeout(() => {
          aiBubble.style.opacity = '1';
          aiBubble.style.transform = 'translateY(0)';
          if (aiCursor) aiCursor.style.display = 'inline';

          // Typewriter effect for AI Answer
          let aiCharIdx = 0;
          if (s40AiTypeInterval) clearInterval(s40AiTypeInterval);

          s40AiTypeInterval = setInterval(() => {
            if (aiCharIdx < s40AiAnswerFull.length) {
              aiTextElem.innerText += s40AiAnswerFull.charAt(aiCharIdx);
              aiCharIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40AiTypeInterval);
              if (aiCursor) aiCursor.style.display = 'inline-block'; // Cursor keeps blinking at end!
            }
          }, 25);
        }, 200);

      } catch (err) { console.log(err); }
    }"""

new_trigger_js = """    function triggerS40SendAI() {
      try {
        if (isS40Sent) return;
        isS40Sent = true;

        const aiBubble = document.getElementById('s40AiBubble');
        const aiTextElem = document.getElementById('s40AiAnswerText');
        const promptCursor = document.getElementById('s40PromptCursor');
        const scrollArea = document.getElementById('s40ChatScrollArea');

        if (!aiBubble || !aiTextElem) return;

        // 1. Hide user prompt cursor immediately upon clicking send!
        if (promptCursor) promptCursor.style.display = 'none';

        // 2. Play Click Sound
        if (typeof playMouseClickSound === 'function') playMouseClickSound();

        // 3. Show AI bubble with fade & scroll
        aiBubble.style.display = 'block';
        setTimeout(() => {
          aiBubble.style.opacity = '1';
          aiBubble.style.transform = 'translateY(0)';

          // Typewriter effect for AI Answer (NO CURSOR!)
          let aiCharIdx = 0;
          if (s40AiTypeInterval) clearInterval(s40AiTypeInterval);

          s40AiTypeInterval = setInterval(() => {
            if (aiCharIdx < s40AiAnswerFull.length) {
              aiTextElem.innerText += s40AiAnswerFull.charAt(aiCharIdx);
              aiCharIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40AiTypeInterval);
            }
          }, 22);
        }, 200);

      } catch (err) { console.log(err); }
    }"""

if content.find(old_trigger_js) != -1:
    content = content.replace(old_trigger_js, new_trigger_js)
    print("Slide 40 triggerS40SendAI updated!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Slide 40 Left Alignment & Strict Cursor Rules Applied!")

