    content = f.read()

# 1. Update ChatGPT container height & padding for spacious presentation:
# Change height: 460px -> height: 500px, width: 1000px -> width: 1040px
# Change AI bubble max-width: 88% -> max-width: 95% (wider speech bubble as requested!)
old_container_html = '<div style="width: 1000px; margin: 0 auto; background: #18181c; border: 1.5px solid #333342; border-radius: 18px; padding: 20px; box-shadow: 0 15px 45px rgba(0,0,0,0.6); display: flex; flex-direction: column; height: 460px; justify-content: space-between;">'
new_container_html = '<div style="width: 1040px; margin: 0 auto; background: #18181c; border: 1.5px solid #333342; border-radius: 18px; padding: 22px; box-shadow: 0 15px 45px rgba(0,0,0,0.6); display: flex; flex-direction: column; height: 500px; justify-content: space-between;">'

if content.find(old_container_html) != -1:
    content = content.replace(old_container_html, new_container_html)

old_ai_width = 'max-width: 88%;'
new_ai_width = 'max-width: 95%;'

if content.find(old_ai_width) != -1:
    content = content.replace(old_ai_width, new_ai_width)

# 2. Strict Cursor Control:
# Prompt cursor initially display: none; ONLY becomes display: inline-block during typing,
# stays blinking AFTER typewriter finishes typing UNTIL triggerS40SendAI() is clicked!
# When triggerS40SendAI() is clicked, promptCursor style.display = 'none' !

old_js_run = """        // Reset
        const userWrapper = document.getElementById('s40UserWrapper');
        if (userWrapper) {
          userWrapper.style.opacity = '0';
          userWrapper.style.transform = 'translateY(10px)';
        }
        aiBubble.style.display = 'none';
        aiBubble.style.opacity = '0';
        promptElem.innerText = '';
        aiTextElem.innerText = '';
        if (promptCursor) promptCursor.style.display = 'inline-block';
        if (aiCursor) aiCursor.style.display = 'none';

        // Step 1: User chat wrapper maps first onto canvas (0.3s)
        setTimeout(() => {
          if (userWrapper) {
            userWrapper.style.opacity = '1';
            userWrapper.style.transform = 'translateY(0)';
          }

          // Step 2: Typewriter types left-to-right inside mapped bubble
          let charIdx = 0;
          s40UserTypeInterval = setInterval(() => {
            if (charIdx < s40UserPromptText.length) {
              promptElem.innerText += s40UserPromptText.charAt(charIdx);
              charIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40UserTypeInterval);
              // Cursor stays blinking at the end!
              if (promptCursor) promptCursor.style.display = 'inline-block';
            }
          }, 18);
        }, 300);"""

new_js_run = """        // Reset
        const userWrapper = document.getElementById('s40UserWrapper');
        if (userWrapper) {
          userWrapper.style.opacity = '0';
          userWrapper.style.transform = 'translateY(10px)';
        }
        aiBubble.style.display = 'none';
        aiBubble.style.opacity = '0';
        promptElem.innerText = '';
        aiTextElem.innerText = '';
        if (promptCursor) promptCursor.style.display = 'inline-block'; // Cursor blinks while waiting for button click!

        // Step 1: User chat wrapper maps first onto canvas (0.3s)
        setTimeout(() => {
          if (userWrapper) {
            userWrapper.style.opacity = '1';
            userWrapper.style.transform = 'translateY(0)';
          }

          // Step 2: Typewriter types left-to-right inside mapped bubble
          let charIdx = 0;
          s40UserTypeInterval = setInterval(() => {
            if (charIdx < s40UserPromptText.length) {
              promptElem.innerText += s40UserPromptText.charAt(charIdx);
              charIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40UserTypeInterval);
              // Cursor stays blinking ONLY until send button is clicked!
              if (promptCursor) promptCursor.style.display = 'inline-block';
            }
          }, 18);
        }, 300);"""

if content.find(old_js_run) != -1:
    content = content.replace(old_js_run, new_js_run)

# Ensure triggerS40SendAI completely hides promptCursor!
old_trigger_js = """        // 1. Hide user prompt cursor immediately upon clicking send!
        if (promptCursor) promptCursor.style.display = 'none';"""

new_trigger_js = """        // 1. Hide user prompt cursor IMMEDIATELY upon clicking send button!
        if (promptCursor) {
          promptCursor.style.display = 'none';
          promptCursor.style.visibility = 'hidden';
        }"""

if content.find(old_trigger_js) != -1:
    content = content.replace(old_trigger_js, new_trigger_js)

