import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# Debugging why Slide 40 disappears on F5 reload:
# 1. Slide 40 container had `id="slide40Container"` but its actual slide index shifted when new divider slides were inserted!
# 2. On window 'load', `syncDynamicSlideNumbers()` runs AFTER `window.location.hash` hash restore!
# Fix: Re-order window load event listeners so `syncDynamicSlideNumbers()` runs BEFORE hash restore, AND ensure `runSlide40Animation()` is safely called regardless of index shifts!

old_hash_restore = """    window.addEventListener('load', syncDynamicSlideNumbers);
window.addEventListener('load', () => {
      try {
        if (window.location.hash) {
          let sNum = parseInt(window.location.hash.replace('#', ''), 10);
          if (!isNaN(sNum) && sNum > 0 && sNum <= total) {
            goTo(sNum - 1);
          }
        }
      } catch (e) { console.log(e); }
    });"""

new_hash_restore = """    // ROBUST WINDOW LOAD & HASH RESTORE (PREVENTS SLIDE DISAPPEARANCE ON F5!)
    window.addEventListener('load', () => {
      try {
        syncDynamicSlideNumbers();
        if (window.location.hash) {
          let sNum = parseInt(window.location.hash.replace('#', ''), 10);
          if (!isNaN(sNum) && sNum > 0 && sNum <= total) {
            goTo(sNum - 1);
          }
        }
      } catch (e) { console.log(e); }
    });"""

if content.find(old_hash_restore) != -1:
    content = content.replace(old_hash_restore, new_hash_restore)
    print("Window load listeners unified and ordered!")

# Ensure Slide 40 animation trigger safely executes when entering slide 40 or any slide with id="slide40Container"
old_goto_trigger = """        if (slides[current] && (slides[current].id === 'slide40Container' || slides[current].querySelector('#s40UserWrapper'))) {
          runSlide40Animation();
        } else {
          if (typeof clearS40Timers === 'function') clearS40Timers();
        }"""

new_goto_trigger = """        if (slides[current] && (slides[current].id === 'slide40Container' || slides[current].querySelector('#s40UserWrapper') || slides[current].querySelector('#s40ChatScrollArea'))) {
          runSlide40Animation();
        } else {
          if (typeof clearS40Timers === 'function') clearS40Timers();
        }"""

if content.find(old_goto_trigger) != -1:
    content = content.replace(old_goto_trigger, new_goto_trigger)
    print("Slide 40 animation trigger query expanded!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Fixed Slide 40 F5 Reload Disappearance Bug!")

