import os

html_path = r'c:\Users\IN\Desktop\꼬리치레\presentation.html'

with open(html_path, 'r', encoding='utf-8') as f:
    content = f.read()

# Fix Slide 40 disappearance bug:
# In CSS/HTML: #s40UserWrapper had inline style `opacity: 0;` in static HTML!
# If JS reset runs or if page loads before animation, #s40UserWrapper remains 100% invisible (`opacity: 0`)!
# Fix: Remove `opacity: 0` from static HTML inline style of #s40UserWrapper, and ensure `runSlide40Animation()` sets `opacity: 1` immediately if elements exist!

old_wrapper_html = '<div id="s40UserWrapper" style="align-self: flex-end; width: 780px; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 16px 20px; text-align: left; opacity: 0; transform: translateY(10px); transition: all 0.5s ease;">'
new_wrapper_html = '<div id="s40UserWrapper" style="align-self: flex-end; width: 780px; background: #2a2b36; border: 1px solid #3f4052; border-radius: 16px 16px 2px 16px; padding: 16px 20px; text-align: left; opacity: 1; transform: translateY(0); transition: all 0.5s ease;">'

if content.find(old_wrapper_html) != -1:
    content = content.replace(old_wrapper_html, new_wrapper_html)
    print("Fixed static HTML opacity: 0 in #s40UserWrapper!")

# Update JS runSlide40Animation() so userWrapper is instantly visible (opacity: 1) without waiting for 300ms timeout bug!
old_run_anim = """    function runSlide40Animation() {
      try {
        isS40Sent = false;
        const userWrapper = document.getElementById('s40UserWrapper');
        const aiBubble = document.getElementById('s40AiBubble');
        const promptElem = document.getElementById('s40PromptText');
        const aiTextElem = document.getElementById('s40AiAnswerText');
        const promptCursor = document.getElementById('s40PromptCursor');
        const aiCursor = document.getElementById('s40AiCursor');
        const scrollArea = document.getElementById('s40ChatScrollArea');

        if (!userWrapper || !aiBubble || !promptElem || !aiTextElem) return;

        if (s40UserTypeInterval) clearInterval(s40UserTypeInterval);
        if (s40AiTypeInterval) clearInterval(s40AiTypeInterval);

        // Reset
        if (userWrapper) {
          userWrapper.style.opacity = '0';
          userWrapper.style.transform = 'translateY(10px)';
        }
        aiBubble.style.display = 'none';
        aiBubble.style.opacity = '0';
        promptElem.innerText = '';
        aiTextElem.innerText = '';
        if (promptCursor) promptCursor.style.display = 'inline-block';
        if (aiCursor) aiCursor.style.display = 'none';

        // Step 1: User chat wrapper maps first onto canvas (0.3s)
        setTimeout(() => {
          if (userWrapper) {
            userWrapper.style.opacity = '1';
            userWrapper.style.transform = 'translateY(0)';
          }

          // Step 2: Typewriter types left-to-right inside mapped bubble
          let charIdx = 0;
          s40UserTypeInterval = setInterval(() => {
            if (charIdx < s40UserPromptText.length) {
              promptElem.innerText += s40UserPromptText.charAt(charIdx);
              charIdx++;
              if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
            } else {
              clearInterval(s40UserTypeInterval);
              // Cursor stays blinking at the end!
              if (promptCursor) promptCursor.style.display = 'inline-block';
            }
          }, 18);
        }, 300);

      } catch (err) { console.log(err); }
    }"""

new_run_anim = """    function runSlide40Animation() {
      try {
        isS40Sent = false;
        const userWrapper = document.getElementById('s40UserWrapper');
        const aiBubble = document.getElementById('s40AiBubble');
        const promptElem = document.getElementById('s40PromptText');
        const aiTextElem = document.getElementById('s40AiAnswerText');
        const promptCursor = document.getElementById('s40PromptCursor');
        const aiCursor = document.getElementById('s40AiCursor');
        const scrollArea = document.getElementById('s40ChatScrollArea');

        if (!userWrapper || !aiBubble || !promptElem || !aiTextElem) return;

        if (s40UserTypeInterval) clearInterval(s40UserTypeInterval);
        if (s40AiTypeInterval) clearInterval(s40AiTypeInterval);

        // Ensure userWrapper is 100% VISIBLE immediately (NO ZERO OPACITY BLANK SCREEN!)
        if (userWrapper) {
          userWrapper.style.opacity = '1';
          userWrapper.style.transform = 'translateY(0)';
        }

        aiBubble.style.display = 'none';
        aiBubble.style.opacity = '0';
        promptElem.innerText = '';
        aiTextElem.innerText = '';
        if (promptCursor) promptCursor.style.display = 'inline-block';
        if (aiCursor) aiCursor.style.display = 'none';

        // Typewriter types left-to-right inside visible bubble
        let charIdx = 0;
        s40UserTypeInterval = setInterval(() => {
          if (charIdx < s40UserPromptText.length) {
            promptElem.innerText += s40UserPromptText.charAt(charIdx);
            charIdx++;
            if (scrollArea) scrollArea.scrollTop = scrollArea.scrollHeight;
          } else {
            clearInterval(s40UserTypeInterval);
            if (promptCursor) promptCursor.style.display = 'inline-block';
          }
        }, 16);

      } catch (err) { console.log(err); }
    }"""

if content.find(old_run_anim) != -1:
    content = content.replace(old_run_anim, new_run_anim)
    print("JS runSlide40Animation() updated to guarantee 100% immediate visibility!")

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(content)

print("SUCCESS: Permanently Fixed Slide 40 Opacity Zero Blank Bug!")

