function syncDynamicSlideNumbers() {
  try {
    const allSlides = document.querySelectorAll('.slide');
    const realTotal = allSlides.length;
    allSlides.forEach((slide, idx) => {
      // Store real DOM index as data attribute for reliable hash restore
      slide.setAttribute('data-slide-real-idx', idx);
      slide.setAttribute('data-slide-num', idx + 1);

      const numBadge = slide.querySelector('.slide-number-badge');
      if (numBadge) numBadge.innerText = (idx + 1);

      const footerSpans = slide.querySelectorAll('.slide-footer span');
      if (footerSpans && footerSpans.length > 1) {
        footerSpans[footerSpans.length - 1].innerText = `Slide ${idx + 1} / ${realTotal}`;
      }
    });
  } catch (e) { console.log(e); }
}

// FINDS REAL DOM INDEX FROM SLIDE NUMBER (after syncDynamicSlideNumbers)
function findSlideIndexByNum(sNum) {
  const allSlides = document.querySelectorAll('.slide');
  for (let i = 0; i < allSlides.length; i++) {
    if (parseInt(allSlides[i].getAttribute('data-slide-num'), 10) === sNum) return i;
  }
  // Fallback: use raw number - 1
  if (sNum > 0 && sNum <= allSlides.length) return sNum - 1;
  return -1;
}

// ROBUST WINDOW LOAD & HASH RESTORE (PREVENTS SLIDE DISAPPEARANCE ON F5!)
window.addEventListener('load', () => {
  try {
    syncDynamicSlideNumbers();
    if (window.location.hash) {
      let sNum = parseInt(window.location.hash.replace('#', ''), 10);
      if (!isNaN(sNum) && sNum > 0) {
        // Use real DOM index lookup — not raw sNum-1!
        const realIdx = findSlideIndexByNum(sNum);
        if (realIdx >= 0) goTo(realIdx);
      }
    }
  } catch (e) { console.log(e); }
});

