let isRestoringHash = false; // Prevent hashchange re-entry loop

function goTo(index) {
  try {
    if (index < 0) index = 0;
    if (index >= total) index = total - 1;
    slides[current].classList.remove('active');
    current = index;
    slides[current].classList.add('active');

    const pBar = document.getElementById('progressBar');
    const pInd = document.getElementById('pageIndicator');
    if (pBar) pBar.style.width = `${((current + 1) / total) * 100}%`;
    if (pInd) pInd.innerText = `${current + 1} / ${total}`;

    // Save to localStorage for reliable F5 restore
    try { localStorage.setItem('ppt_slide', current); } catch(e) {}

    // Save current slide number in URL hash (guard against hashchange loop)
    isRestoringHash = true;
    window.location.hash = '#' + (current + 1);
    setTimeout(() => { isRestoringHash = false; }, 50);

    // Trigger slide-specific safe simulators
    if (current === 8) runStep09Safe(1);
    if (current === 9) startLegoLoop10Safe();
    if (current === 10) startH123LoopSafe();
    if (current === 11) initSlide12Safe();
    if (current === 37) runSlide38Animation();
    if (slides[current] && (slides[current].id === 'slide43Container' || slides[current].querySelector('#s43RecordRow'))) runSlide43Animation();
    if (slides[current] && (slides[current].id === 'slide40Container' || slides[current].querySelector('#s40UserWrapper') || slides[current].querySelector('#s40ChatScrollArea'))) {
      runSlide40Animation();
    } else {
      if (typeof clearS40Timers === 'function') clearS40Timers();
    }

    if (current === 29) {
      if (typeof startStepAutoLoop30 === 'function') startStepAutoLoop30();
    } else {
      if (typeof closeStepModal30 === 'function') closeStepModal30();
      if (typeof autoStepLoopTimer30 !== 'undefined' && autoStepLoopTimer30) {
        clearInterval(autoStepLoopTimer30);
        autoStepLoopTimer30 = null;
      }
    }
  } catch (e) { console.log(e); }
}

