window.addEventListener('load', () => {
  try {
    syncDynamicSlideNumbers();

    // Determine target slide: localStorage first, then URL hash
    let targetIdx = -1;
    try {
      const saved = localStorage.getItem('ppt_slide');
      if (saved !== null) targetIdx = parseInt(saved, 10);
    } catch(e) {}

    if (window.location.hash) {
      let sNum = parseInt(window.location.hash.replace('#', ''), 10);
      if (!isNaN(sNum) && sNum > 0) {
        const hashIdx = findSlideIndexByNum(sNum);
        if (hashIdx >= 0) targetIdx = hashIdx; // hash takes priority
      }
    }

    if (targetIdx > 0 && targetIdx < total) {
      // Delay goTo until AFTER the browser has painted the initial frame
      // This prevents CSS transition from being skipped on load
      requestAnimationFrame(() => {
        setTimeout(() => { goTo(targetIdx); }, 20);
      });
    }
  } catch (e) { console.log(e); }
});

