// --- SLIDE 16 REAL-TIME 15MIN PRACTICE TIMER & CHECKLIST LOGIC ---
let timer16Seconds = 900; // 15분 = 900초
let timer16Interval = null;
let missionState16 = [false, false, false, false];

function updateTimerDisplay16() {
  try {
    const display = document.getElementById('practiceTimerDisplay16');
    if (!display) return;
    let m = Math.floor(timer16Seconds / 60);
    let s = timer16Seconds % 60;
    let mStr = m < 10 ? '0' + m : '' + m;
    let sStr = s < 10 ? '0' + s : '' + s;
    display.innerText = `${mStr}:${sStr}`;
  } catch (err) { console.log(err); }
}

function startPracticeTimer16() {
  try {
    if (timer16Interval) clearInterval(timer16Interval);
    timer16Interval = setInterval(() => {
      if (timer16Seconds > 0) {
        timer16Seconds--;
        updateTimerDisplay16();
      } else {
        clearInterval(timer16Interval);
      }
    }, 1000);
  } catch (err) { console.log(err); }
}

function pausePracticeTimer16() {
  try {
    if (timer16Interval) clearInterval(timer16Interval);
  } catch (err) { console.log(err); }
}

function resetPracticeTimer16() {
  try {
    if (timer16Interval) clearInterval(timer16Interval);
    timer16Seconds = 900;
    updateTimerDisplay16();
  } catch (err) { console.log(err); }
}

