function runSlide45Animation() {
  try {
    isS45CoverAdded = false;
    isS45EmojiAdded = false;

    const coverBtn = document.getElementById('s45CoverBtn');
    const coverBanner = document.getElementById('s45CoverBanner');
    const emojiBtn = document.getElementById('s45EmojiBtn');
    const emojiDisplay = document.getElementById('s45EmojiDisplay');

    if (coverBtn) {
      coverBtn.style.opacity = '1';
      coverBtn.style.transform = 'scale(1)';
      coverBtn.style.pointerEvents = 'auto';
    }
    if (coverBanner) {
      coverBanner.style.height = '0px';
      coverBanner.style.opacity = '0';
    }
    if (emojiBtn) {
      emojiBtn.style.display = 'flex';
      emojiBtn.style.opacity = '1';
      emojiBtn.style.transform = 'scale(1)';
      emojiBtn.style.pointerEvents = 'auto';
    }
    if (emojiDisplay) {
      emojiDisplay.style.display = 'none';
      emojiDisplay.style.opacity = '0';
      emojiDisplay.style.transform = 'scale(0.5)';
    }
  } catch (err) { console.log(err); }
}

function triggerS45AddCover() {
  try {
    if (isS45CoverAdded) return;
    isS45CoverAdded = true;

    const coverBtn = document.getElementById('s45CoverBtn');
    const coverBanner = document.getElementById('s45CoverBanner');

    if (typeof playMouseClickSound === 'function') playMouseClickSound();

    if (coverBtn) {
      coverBtn.style.opacity = '0';
      coverBtn.style.transform = 'scale(0.8)';
      coverBtn.style.pointerEvents = 'none';
    }

    setTimeout(() => {
      if (coverBanner) {
        coverBanner.style.height = '110px';
        coverBanner.style.opacity = '1';
      }
    }, 150);

  } catch (err) { console.log(err); }
}

function triggerS45AddEmoji() {
  try {
    if (isS45EmojiAdded) return;
    isS45EmojiAdded = true;

    const emojiBtn = document.getElementById('s45EmojiBtn');
    const emojiDisplay = document.getElementById('s45EmojiDisplay');

    if (typeof playMouseClickSound === 'function') playMouseClickSound();

    if (emojiBtn) {
      emojiBtn.style.opacity = '0';
      emojiBtn.style.transform = 'scale(0.8)';
      emojiBtn.style.pointerEvents = 'none';
    }

    setTimeout(() => {
      if (emojiBtn) emojiBtn.style.display = 'none';
      if (emojiDisplay) {
        emojiDisplay.style.display = 'block';
        setTimeout(() => {
          emojiDisplay.style.opacity = '1';
          emojiDisplay.style.transform = 'scale(1)';
        }, 30);
      }
    }, 200);

  } catch (err) { console.log(err); }
}

