// --- SLIDE 45 COVER & EMOJI INTERACTIVE SIMULATOR LOGIC ---
let isS45CoverAdded = false;
let isS45EmojiAdded = false;

function runSlide45Animation() {
  try {
    isS45CoverAdded = false;
    isS45EmojiAdded = false;

    const coverBtn = document.getElementById('s45CoverBtn');
    const layoutBtn1 = document.getElementById('s45LayoutBtn1');
    const coverBanner = document.getElementById('s45CoverBanner');
    const titleWrapper1 = document.getElementById('s45TitleWrapper1');

    const emojiBtn = document.getElementById('s45EmojiBtn');
    const layoutBtn2 = document.getElementById('s45LayoutBtn2');
    const pickerPopup = document.getElementById('s45EmojiPickerPopup');
    const virtualMouse = document.getElementById('s45VirtualMouse');
    const emojiDisplay = document.getElementById('s45EmojiDisplay');

    if (coverBtn) {
      coverBtn.style.opacity = '1';
      coverBtn.style.transform = 'scale(1)';
      coverBtn.style.pointerEvents = 'auto';
    }
    if (layoutBtn1) {
      layoutBtn1.style.opacity = '1';
      layoutBtn1.style.pointerEvents = 'auto';
    }
    if (coverBanner) {
      coverBanner.style.height = '0px';
      coverBanner.style.opacity = '0';
    }
    if (titleWrapper1) {
      titleWrapper1.style.padding = '14px 16px';
    }

    if (emojiBtn) {
      emojiBtn.style.display = 'flex';
      emojiBtn.style.opacity = '1';
      emojiBtn.style.transform = 'scale(1)';
      emojiBtn.style.pointerEvents = 'auto';
    }
    if (layoutBtn2) {
      layoutBtn2.style.opacity = '1';
      layoutBtn2.style.pointerEvents = 'auto';
    }
    if (pickerPopup) {
      pickerPopup.style.display = 'none';
      pickerPopup.style.opacity = '0';
      pickerPopup.style.transform = 'translateY(-8px)';
    }
    if (virtualMouse) {
      virtualMouse.style.opacity = '0';
      virtualMouse.style.top = '110px';
      virtualMouse.style.left = '150px';
    }
    if (emojiDisplay) {
      emojiDisplay.style.display = 'none';
      emojiDisplay.style.opacity = '0';
      emojiDisplay.style.transform = 'scale(0.5)';
    }
  } catch (err) { console.log(err); }
}

function triggerS45AddCover() {
  try {
    if (isS45CoverAdded) return;
    isS45CoverAdded = true;

    const coverBtn = document.getElementById('s45CoverBtn');
