const fs = require('fs');
const html = fs.readFileSync('presentation.html', 'utf8');

// Find all slide divisions
const slideRegex = /<div class="slide[^"]*"/g;
let match;
let count = 0;
while ((match = slideRegex.exec(html)) !== null) {
  count++;
}
console.log('✅ 총 슬라이드 엘리먼트 수:', count);

// Check if any slide div is nested inside another slide
const scriptStart = html.indexOf('<script>');
const scriptContent = html.substring(scriptStart + 8, html.lastIndexOf('</script>'));
try {
  new Function(scriptContent);
  console.log('✅ JS Syntax Check: PASSED!');
} catch (e) {
  console.error('❌ JS Error:', e.message);
}

const fs = require('fs');
const html = fs.readFileSync('presentation.html', 'utf8');

const matches = html.match(/<div class="slide["\s]/g);
console.log('✅ 탑레벨 .slide 디브 수:', matches ? matches.length : 0);

// 슬라이드 46~48 구간의 하드코딩 푸터 텍스트 확인
const lines = html.split('\n');
lines.forEach((line, idx) => {
  if (line.includes('Slide ') && line.includes('/ 60')) {
    console.log(`L${idx + 1}: ${line.trim()}`);
  }
});

const fs = require('fs');
let html = fs.readFileSync('presentation.html', 'utf8');

// Replace all legacy <span>Slide XX / 60</span> or <span>Slide XX / 63</span> with dynamic badge class
html = html.replace(/<span>Slide \d+ \/ \d+<\/span>/g, '<span class="slide-dynamic-badge"></span>');

fs.writeFileSync('presentation.html', html, 'utf8');
console.log('✅ 모든 슬라이드 푸터의 하드코딩 Slide XX / XX 표시를 slide-dynamic-badge 로 일괄 전환 완료!');

