function goTo(index) {
  try {
    const liveSlides = document.querySelectorAll('.slide');
    const realTotal = liveSlides.length;
    if (index < 0) index = 0;
    if (index >= realTotal) index = realTotal - 1;

    slides[current].classList.remove('active');
    current = index;
    if (slides[current]) slides[current].classList.add('active');

    const pBar = document.getElementById('progressBar');
    const pInd = document.getElementById('pageIndicator');
    if (pBar) pBar.style.width = `${((current + 1) / realTotal) * 100}%`;
    if (pInd) pInd.innerText = `${current + 1} / ${realTotal}`;

    // Save to localStorage for reliable F5 restore
    try { localStorage.setItem('ppt_slide', current); } catch(e) {}

