function openS50SortModal() {
  try {
    const overlay = document.getElementById('s50SortModalOverlay');
    const container = document.getElementById('s50SortModalContainer');
    if (!overlay || !container) return;

    if (typeof playMouseClickSound === 'function') playMouseClickSound();

    overlay.style.display = 'flex';
    setTimeout(() => {
      overlay.style.opacity = '1';
      container.style.transform = 'scale(1)';
    }, 20);

    s50SortCurrentStep = 0;
    renderS50SortModalStep(0);

    if (s50SortLoopTimer) clearInterval(s50SortLoopTimer);
    s50SortLoopTimer = setInterval(() => {
      s50SortCurrentStep = (s50SortCurrentStep + 1) % 3; // 0 -> 1 -> 2 -> 0
      renderS50SortModalStep(s50SortCurrentStep);
    }, 3000); // 3 seconds loop!

  } catch (e) { console.log(e); }
}

function closeS50SortModal() {
  try {
    const overlay = document.getElementById('s50SortModalOverlay');
    const container = document.getElementById('s50SortModalContainer');
    if (s50SortLoopTimer) {
      clearInterval(s50SortLoopTimer);
      s50SortLoopTimer = null;
    }
    if (!overlay || !container) return;

    container.style.transform = 'scale(0.88)';
    overlay.style.opacity = '0';
    setTimeout(() => {
      overlay.style.display = 'none';
    }, 250);
  } catch (e) { console.log(e); }
}

