// --- SLIDE 51 INTERACTIVE CHECKLIST LOGIC ---
const s51CheckState = { 1: false, 2: false, 3: false, 4: false, 5: false, 6: false };

function toggleS51Check(num) {
  try {
    if (typeof playMouseClickSound === 'function') playMouseClickSound();

    s51CheckState[num] = !s51CheckState[num];
    const isChecked = s51CheckState[num];

    const item = document.getElementById('s51Item' + num);
    const box = document.getElementById('s51Box' + num);
