        box.innerHTML = '✓';
      }
      if (text) {
        text.style.textDecoration = 'line-through';
        text.style.color = '#6b7280';
        text.style.opacity = '0.6';
      }
      if (item) {
        item.style.background = 'rgba(139,92,246,0.08)';
        item.style.borderColor = '#8b5cf6';
      }
      if (tag) {
        tag.style.background = 'rgba(16,185,129,0.2)';
        tag.style.color = '#6ee7b7';
        tag.style.borderColor = '#10b981';
        tag.innerText = '✅ 완료됨';
      }
    } else {
      if (box) {
        box.style.background = 'transparent';
        box.style.borderColor = '#8b5cf6';
        box.innerHTML = '';
      }
      if (text) {
        text.style.textDecoration = 'none';
        text.style.color = '#e2e8f0';
        text.style.opacity = '1';
      }
      if (item) {
        item.style.background = '#1a1a20';
        item.style.borderColor = '#2e2e3e';
      }
      if (tag) {
        tag.style.background = 'rgba(139,92,246,0.2)';
        tag.style.color = '#c4b5fd';
        tag.style.borderColor = '#8b5cf6';
        tag.innerText = '클릭하여 완료';
      }
    }

    // UPDATE PROGRESS BAR
    let checkedCount = 0;
    for (let i = 1; i <= 6; i++) {
      if (s51CheckState[i]) checkedCount++;
    }

    const bar = document.getElementById('s51ProgressBar');
    const countText = document.getElementById('s51ProgressText');
    if (bar) {
      bar.style.width = (checkedCount / 6 * 100) + '%';
    }
    if (countText) {
      countText.innerText = checkedCount + ' / 6 완료' + (checkedCount === 6 ? ' 🎉' : '');
    }

  } catch (e) { console.log(e); }
}

