// --- SLIDE 53: 30MIN COMPREHENSIVE COACHING TIMER LOGIC ---
let s53TimerInterval = null;
let s53SecondsLeft = 30 * 60; // 30 minutes

function updateS53TimerDisplay() {
  const mins = Math.floor(s53SecondsLeft / 60);
  const secs = s53SecondsLeft % 60;
  const display = document.getElementById('s53TimerDisplay');
  if (display) {
    display.innerText = String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
  }
}

function startTimer53() {
  if (typeof playMouseClickSound === 'function') playMouseClickSound();
  if (s53TimerInterval) return;

  s53TimerInterval = setInterval(() => {
    if (s53SecondsLeft > 0) {
      s53SecondsLeft--;
      updateS53TimerDisplay();
    } else {
      clearInterval(s53TimerInterval);
      s53TimerInterval = null;
      alert('⏰ 4주차 이력 DB 최종 종합 실습 30분이 완료되었습니다!');
    }
  }, 1000);
}

function pauseTimer53() {
  if (typeof playMouseClickSound === 'function') playMouseClickSound();
  if (s53TimerInterval) {
    clearInterval(s53TimerInterval);
    s53TimerInterval = null;
  }
}

function resetTimer53() {
  if (typeof playMouseClickSound === 'function') playMouseClickSound();
  pauseTimer53();
  s53SecondsLeft = 30 * 60;
  updateS53TimerDisplay();
}

