// --- SLIDE 52: FULL WIDTH & SMALL TEXT DISPLAY OPTION CENTER MODAL LOGIC ---
let s52FWCurrentStep = 0;
let s52FWTimer = null;

function openS52FullWidthModal() {
  try {
    if (typeof playMouseClickSound === 'function') playMouseClickSound();
    s52FWCurrentStep = 0;
    renderS52FullWidthModalStep(0);

    const overlay = document.getElementById('s52FullWidthModalOverlay');
    const container = document.getElementById('s52FullWidthModalContainer');
    if (!overlay || !container) return;

    overlay.style.display = 'flex';
    requestAnimationFrame(() => {
      overlay.style.opacity = '1';
      container.style.transform = 'scale(1)';
    });

    if (s52FWTimer) clearInterval(s52FWTimer);
    s52FWTimer = setInterval(() => {
      s52FWCurrentStep = (s52FWCurrentStep + 1) % 3;
      renderS52FullWidthModalStep(s52FWCurrentStep);
    }, 3000);
  } catch (err) { console.log(err); }
}

function closeS52FullWidthModal() {
  try {
    if (s52FWTimer) { clearInterval(s52FWTimer); s52FWTimer = null; }
    const overlay = document.getElementById('s52FullWidthModalOverlay');
    const container = document.getElementById('s52FullWidthModalContainer');
    if (!overlay || !container) return;

    container.style.transform = 'scale(0.88)';
    overlay.style.opacity = '0';
    setTimeout(() => { overlay.style.display = 'none'; }, 250);
  } catch (err) { console.log(err); }
}

function manualSelectS52FWStep(step) {
  if (typeof playMouseClickSound === 'function') playMouseClickSound();
  s52FWCurrentStep = step;
  renderS52FullWidthModalStep(step);
}

