// --- SLIDE 52: PRECISION REALTIME SIMULATION ENGINE ---

// 1. FULL WIDTH (전체 너비): Initial state right-aligned (margin-left: auto), mouse glides directly to toggle switch, clicks, then expands smoothly!
let s52FWState = false;
let s52FWInterval = null;

function openS52FullWidthModal() {
  try {
    if (typeof playMouseClickSound === 'function') playMouseClickSound();
    s52FWState = false;
    renderS52FullWidthLive(false);

    const overlay = document.getElementById('s52FullWidthModalOverlay');
    const container = document.getElementById('s52FullWidthModalContainer');
    if (!overlay || !container) return;

    overlay.style.display = 'flex';
    requestAnimationFrame(() => {
      overlay.style.opacity = '1';
      container.style.transform = 'scale(1)';
    });

    if (s52FWInterval) clearInterval(s52FWInterval);
    s52FWInterval = setInterval(() => {
      s52FWState = !s52FWState;
      renderS52FullWidthLive(s52FWState);
    }, 3600);
  } catch (err) { console.log(err); }
}

function closeS52FullWidthModal() {
  try {
    if (s52FWInterval) { clearInterval(s52FWInterval); s52FWInterval = null; }
    const overlay = document.getElementById('s52FullWidthModalOverlay');
    const container = document.getElementById('s52FullWidthModalContainer');
    if (!overlay || !container) return;

    container.style.transform = 'scale(0.88)';
    overlay.style.opacity = '0';
    setTimeout(() => { overlay.style.display = 'none'; }, 250);
  } catch (err) { console.log(err); }
}

function renderS52FullWidthLive(isOn) {
  try {
    const body = document.getElementById('s52FullWidthModalBody');
    const badge = document.getElementById('s52FWStatusBadge');
    if (!body) return;

    if (badge) {
      badge.innerText = isOn ? '↔ 전체 너비 [ON: 스크롤 없이 시원한 넓이]' : '↔ 전체 너비 [OFF: 우측 정렬 기본 좁은 여백]';
      badge.style.background = isOn ? '#10b981' : '#4b5563';
      badge.style.color = isOn ? '#000' : '#fff';
    }

    body.innerHTML = `
      <div style="position: relative; font-size: 13px;">
        <!-- TOP NOTION TOOLBAR HEADER -->
        <div style="display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #2d2d3d; padding-bottom: 10px; margin-bottom: 14px;">
          <div style="font-weight: 900; color: #fff; font-size: 16px;">오진실의 개인 이력 DB</div>
          <div style="display: flex; align-items: center; gap: 8px;">
            <span style="color: #9ca3af; font-size: 12px;">지금 편집</span>
            <span style="color: #9ca3af; font-size: 12px;">🔒 공유</span>
            <span style="background: rgba(16,185,129,0.25); color: #6ee7b7; border: 1px solid #10b981; padding: 2px 8px; border-radius: 6px; font-weight: 900;">...</span>
          </div>
        </div>

        <!-- MAIN NOTION CANVAS (BEFORE TOGGLE: RIGHT ALIGNED margin-left: auto; AFTER TOGGLE: 100% SMOOTH EXTENSION) -->
        <div style="background: #18181c; border: 1.5px solid ${isOn ? '#10b981' : '#333342'}; border-radius: 12px; padding: 16px; transition: all 0.9s cubic-bezier(0.16, 1, 0.3, 1); width: ${isOn ? '100%' : '60%'}; margin-left: auto; box-shadow: 0 10px 30px rgba(0,0,0,0.6); position: relative;">

          <!-- TOGGLE PANEL ROW -->
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; background: rgba(255,255,255,0.04); padding: 8px 14px; border-radius: 8px; border: 1px solid ${isOn ? '#10b981' : 'rgba(255,255,255,0.08)'};">
            <span style="font-weight: 800; color: ${isOn ? '#6ee7b7' : '#d1d5db'}; font-size: 13.5px;">↔ 전체 너비</span>

            <!-- TOGGLE SWITCH UI WITH EXACT POINTER TARGET ANCHOR -->
            <div style="position: relative;">
              <div style="width: 46px; height: 24px; background: ${isOn ? '#2563eb' : '#4b5563'}; border-radius: 12px; display: flex; align-items: center; justify-content: ${isOn ? 'flex-end' : 'flex-start'}; padding: 2px; transition: all 0.3s ease; box-shadow: ${isOn ? '0 0 10px #2563eb' : 'none'};">
                <span style="width: 20px; height: 20px; background: #fff; border-radius: 50%;"></span>
              </div>

              <!-- REALISTIC SVG MOUSE CURSOR LANDING EXACTLY ON THE TOGGLE SWITCH -->
              <div style="position: absolute; top: 2px; left: 12px; z-index: 50; pointer-events: none; animation: mousePointerGlideIn 1.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style="filter: drop-shadow(0 4px 12px rgba(0,0,0,0.9));">
                  <path d="M5.5 3.5L18.5 11.5L12.5 13.5L9.5 19.5L5.5 3.5Z" fill="#10b981" stroke="#ffffff" stroke-width="2" stroke-linejoin="round"/>
                </svg>
              </div>
            </div>
          </div>

          <!-- NOTION DB TABLE -->
          <div style="overflow-x: auto; width: 100%;">
            <table style="width: 100%; border-collapse: collapse; font-size: 12.5px; text-align: left; white-space: nowrap;">
              <thead>
                <tr style="border-bottom: 1.5px solid #3d3d4e; background: #222228;">
                  <th style="padding: 8px 10px; color: #fff;">Aa 경험명</th>
                  <th style="padding: 8px 10px; color: #fff;">🔽 경험유형</th>
                  <th style="padding: 8px 10px; color: #fff;">📅 기간</th>
                  <th style="padding: 8px 10px; color: #fff;">☰ 나의역할</th>
                  <th style="padding: 8px 10px; color: #fff;">:≡ 주요 역량</th>
                  <th style="padding: 8px 10px; color: #fff;">🏆 결과/성과</th>
                </tr>
              </thead>
              <tbody>
                <tr style="border-bottom: 1px solid #282834;">
                  <td style="padding: 8px 10px; color: #fff; font-weight: 800;">🎪 밀양 지역축제 현장지원</td>
                  <td style="padding: 8px 10px;"><span style="background: rgba(245,158,11,0.2); color: #fde68a; padding: 2px 6px; border-radius: 4px; font-size: 11px;">대외활동</span></td>
                  <td style="padding: 8px 10px; color: #9ca3af;">2024.05 - 2024.06</td>
                  <td style="padding: 8px 10px; color: #9ca3af;">현장 안내 및 아동 체험 운영</td>
                  <td style="padding: 8px 10px;"><span style="background: rgba(139,92,246,0.2); color: #c4b5fd; padding: 2px 6px; border-radius: 4px; font-size: 11px;">#고객응대</span></td>
                  <td style="padding: 8px 10px; color: #6ee7b7;">방문객 1,200명 만족도 98%</td>
                </tr>
              </tbody>
            </table>
          </div>

        </div>
      </div>
    `;
  } catch (err) { console.log(err); }
}

