// --- SLIDE 52: PAGE LOCK LIVE DISAPPEARING OPTIONS SIMULATOR ---
let s52PLState = false;
let s52PLInterval = null;

function openS52PageLockModal() {
  try {
    if (typeof playMouseClickSound === 'function') playMouseClickSound();
    s52PLState = false;
    renderS52PageLockLive(false);

    const overlay = document.getElementById('s52PageLockModalOverlay');
    const container = document.getElementById('s52PageLockModalContainer');
    if (!overlay || !container) return;

    overlay.style.display = 'flex';
    requestAnimationFrame(() => {
      overlay.style.opacity = '1';
      container.style.transform = 'scale(1)';
    });

    if (s52PLInterval) clearInterval(s52PLInterval);
    s52PLInterval = setInterval(() => {
      s52PLState = !s52PLState;
      renderS52PageLockLive(s52PLState);
    }, 3500);
  } catch (err) { console.log(err); }
}

function closeS52PageLockModal() {
  try {
    if (s52PLInterval) { clearInterval(s52PLInterval); s52PLInterval = null; }
    const overlay = document.getElementById('s52PageLockModalOverlay');
    const container = document.getElementById('s52PageLockModalContainer');
    if (!overlay || !container) return;

    container.style.transform = 'scale(0.88)';
    overlay.style.opacity = '0';
    setTimeout(() => { overlay.style.display = 'none'; }, 250);
  } catch (err) { console.log(err); }
}

