function applyS52PageLockDOM(isLocked) {
  s52PLState = isLocked;
  const disappearElements = document.querySelectorAll('.s52-pl-disappear');
  const notice = document.getElementById('s52PLLockedNotice');
  const switchBg = document.getElementById('s52PLSwitchBg');
  const badge = document.getElementById('s52PLStatusBadge');

  disappearElements.forEach(el => {
    el.style.opacity = isLocked ? '0' : '1';
    el.style.maxHeight = isLocked ? '0px' : '300px';
    el.style.margin = isLocked ? '0' : '';
    el.style.padding = isLocked ? '0' : '';
  });

  if (notice) notice.style.display = isLocked ? 'block' : 'none';
  if (switchBg) {
    switchBg.style.background = isLocked ? '#2563eb' : '#4b5563';
    switchBg.style.justifyContent = isLocked ? 'flex-end' : 'flex-start';
  }
  if (badge) {
    badge.innerText = isLocked ? '🔒 페이지 잠금 [ON: 사진 2의 콤팩트 축소 메뉴]' : '🔒 페이지 잠금 [OFF: 사진 1의 전체 옵션 노출]';
    badge.style.background = isLocked ? '#8b5cf6' : '#4b5563';
    badge.style.color = '#fff';
  }
}

function closeS52PageLockModal() {
  try {
    if (s52PLTimer) clearTimeout(s52PLTimer);
    const overlay = document.getElementById('s52PageLockModalOverlay');
    const container = document.getElementById('s52PageLockModalContainer');
    if (!overlay || !container) return;

    container.style.transform = 'scale(0.88)';
    overlay.style.opacity = '0';
    setTimeout(() => { overlay.style.display = 'none'; }, 250);
  } catch (err) { console.log(err); }
}

