// SLIDE 56 NOTION TO-DO CHECKBOX INTERACTIVE LOGIC
const s56CheckStates = { 1: true, 2: true, 3: true, 4: true };

function toggleS56Check(id) {
  s56CheckStates[id] = !s56CheckStates[id];
  const isChecked = s56CheckStates[id];

  const box = document.getElementById('s56Box' + id);
  const text = document.getElementById('s56Text' + id);
  const card = document.getElementById('s56Card' + id);

  if (box) {
    box.style.background = isChecked ? '#2563eb' : 'rgba(255,255,255,0.05)';
    box.style.borderColor = isChecked ? '#3b82f6' : '#4b5563';
    box.innerText = isChecked ? '✓' : '';
  }

  if (text) {
    text.style.textDecoration = isChecked ? 'line-through' : 'none';
    text.style.opacity = isChecked ? '0.85' : '1';
  }

  if (card) {
    card.style.opacity = isChecked ? '1' : '0.6';
  }

  // Update progress bar
  let completedCount = 0;
  for (let i = 1; i <= 4; i++) {
    if (s56CheckStates[i]) completedCount++;
  }

  const percent = (completedCount / 4) * 100;
  const fill = document.getElementById('s56ProgressBarFill');
  const badge = document.getElementById('s56ProgressBadge');

  if (fill) fill.style.width = percent + '%';
  if (badge) {
    badge.innerText = `${completedCount} / 4 항목 완료 (${percent}% ${percent === 100 ? '🎉' : ''})`;
    badge.style.background = percent === 100 ? 'rgba(16,185,129,0.2)' : 'rgba(245,158,11,0.2)';
    badge.style.color = percent === 100 ? '#6ee7b7' : '#fde68a';
    badge.style.borderColor = percent === 100 ? '#10b981' : '#f59e0b';
  }
}

