.slide {
  position: absolute;
  top: 0; left: 0;
  width: 1280px;
  height: 720px;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 0px !important;
  padding: 45px 65px;
  opacity: 0;
  visibility: hidden;
  transform: translateX(50px) scale(0.98);
  transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1), transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.4s;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  box-shadow: 0 25px 60px rgba(0,0,0,0.6);
}

.slide.active {
  opacity: 1 !important;
  visibility: visible !important;
  transform: translateX(0) scale(1) !important;
}

.slide-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
}

.slide-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--purple-light);
  text-transform: uppercase;
}

.slide-meta-tag {
  background: rgba(0, 102, 79, 0.3);
  border: 1px solid var(--card-border);
  padding: 4px 10px;
  border-radius: 0px !important;
}

.slide-number-badge {
  font-size: 26px;
  font-weight: 800;
  color: rgba(255,255,255,0.15);
}

.slide-title-group h2 {
  font-size: 32px;
  font-weight: 800;
  line-height: 1.25;
  color: #fff;
  margin-top: 4px;
  letter-spacing: -0.02em;
}

.slide-title-group p {
  font-size: 17px;
  color: var(--text-sub);
  margin-top: 6px;
  font-weight: 400;
}

.slide-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-muted);
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 14px;
  margin-top: auto;
}

.content-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  margin: 10px 0;
  gap: 16px;
}

.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.grid-5 { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; }

.card {
  background: var(--gradient-card);
  background-color: rgba(20, 43, 36, 0.6);
  border: 1px solid var(--card-border);
  border-radius: 0px !important;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: all 0.3s ease;
}
.card:hover {
  border-color: #34d399;
  transform: translateY(-2px);
}
.card-accent { border-left: 4px solid var(--purple); }
.card-cyan { border-left: 4px solid var(--cyan); }
.card-emerald { border-left: 4px solid var(--emerald); }
.card-amber { border-left: 4px solid var(--amber); }
.card-rose { border-left: 4px solid #f43f5e; }

.card-num {
  font-size: 22px;
  font-weight: 800;
  color: var(--purple-light);
}
.card-title {
  font-size: 19px;
  font-weight: 700;
  color: #fff;
}
.card-desc {
  font-size: 14px;
  color: var(--text-sub);
  line-height: 1.5;
}

.callout {
  background: rgba(0, 102, 79, 0.2);
  border: 1px solid var(--card-border);
  border-radius: 0px !important;
  padding: 16px 20px;
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--text-main);
  font-size: 15px;
  font-weight: 500;
}
.callout-icon { font-size: 22px; }

.ai-note {
  background: rgba(255, 224, 102, 0.1);
  border: 1px solid rgba(255, 224, 102, 0.3);
