const fs = require('fs');
const lines = fs.readFileSync('presentation.html', 'utf8').split('\n');
let slideIndex = 0;
let depth = 0;
lines.forEach((line, idx) => {
  if (line.includes('class="slide')) {
    if (slideIndex > 0 && depth !== 0) {
      console.log(`Slide ${slideIndex} at line ${idx+1} is unbalanced! (depth: ${depth})`);
    }
    slideIndex++;
    depth = 0;
  }
  const open = (line.match(/<div[\s>]/gi) || []).length;
  const close = (line.match(/<\/div>/gi) || []).length;
  depth += open - close;
});
if (depth !== 0) {
  console.log(`Slide ${slideIndex} (last slide) is unbalanced! (depth: ${depth})`);
}

